CREATE TABLE IF NOT EXISTS dictionary_terms (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  title            TEXT NOT NULL,
  slug             TEXT NOT NULL UNIQUE,
  short_definition TEXT NOT NULL,
  full_description TEXT,
  ai_explanation   TEXT,
  related_terms    TEXT,
  quiz_question    TEXT,
  quiz_options     TEXT,
  quiz_answer      INTEGER DEFAULT 0,
  seo_title        TEXT,
  seo_description  TEXT,
  access_level     TEXT DEFAULT 'pro' CHECK(access_level IN ('free','login','pro')),
  status           TEXT DEFAULT 'active' CHECK(status IN ('active','inactive')),
  created_at       TEXT DEFAULT (datetime('now')),
  updated_at       TEXT DEFAULT (datetime('now'))
);

INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Permanent Resident', 'permanent-resident', 'A person granted the right to live and work in Canada permanently without being a Canadian citizen.', 'A permanent resident (PR) has most rights of Canadian citizens, including access to healthcare, education, and the right to work anywhere in Canada. PRs must maintain status by being physically present in Canada for at least 730 days in every 5-year period. They cannot vote in federal elections or hold a Canadian passport. After meeting residency and language requirements, PRs may apply for citizenship.', 'Think of a permanent resident as someone with a ''long-term guest pass'' for Canada. You can live, work, and access public services freely — but you haven''t fully joined Canada as a citizen yet. Stay for at least 2 out of every 5 years or you could lose the status.', '[{"title":"Canadian Citizen","slug":"canadian-citizen"},{"title":"Permanent Resident Card","slug":"permanent-resident-card"},{"title":"Citizenship Test","slug":"citizenship-test"}]', 'How many days must a permanent resident be physically present in Canada within a 5-year period?', '["365 days","548 days","730 days","900 days"]', 2, 'Permanent Resident — Canadian Citizenship Glossary | PassPilot', 'What is a permanent resident in Canada? Learn PR rights, responsibilities, and the path to citizenship. Free glossary.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Canadian Citizen', 'canadian-citizen', 'A person who is a full legal member of Canada, either by birth, descent, or naturalization.', 'Canadian citizens enjoy all rights in Canada, including the right to vote, hold a Canadian passport, and run for political office. Citizenship can be acquired by birth in Canada, birth abroad to a Canadian parent, or by applying for citizenship after meeting residency, language, and knowledge requirements. Canadian citizens cannot have their citizenship revoked except in specific circumstances such as fraud.', 'A Canadian citizen is the highest level of membership in Canada. Unlike a permanent resident, a citizen can vote, get a Canadian passport, and can never be forced to leave Canada. It''s like the difference between renting a home (PR) and owning it (citizen).', '[{"title":"Permanent Resident","slug":"permanent-resident"},{"title":"Oath of Citizenship","slug":"oath-of-citizenship"},{"title":"Citizenship Certificate","slug":"citizenship-certificate"}]', 'Which of the following is a right that Canadian citizens have but permanent residents do NOT?', '["Access to healthcare","The right to vote in federal elections","The right to work in Canada","Access to public education"]', 1, 'Canadian Citizen — Canadian Citizenship Glossary | PassPilot', 'What is a Canadian citizen? Learn about rights, how to become one, and the difference from a permanent resident.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Citizenship Test', 'citizenship-test', 'A written exam that tests knowledge of Canada''s history, values, government, and laws required to become a citizen.', 'The Canadian citizenship test consists of 20 multiple-choice questions based on the Discover Canada study guide. Applicants must score at least 15 out of 20 (75%) to pass. The test covers topics including Canadian history, government, rights and responsibilities, and symbols. Most adults aged 18–54 applying for citizenship must take the test.', 'The citizenship test is like a ''final exam'' to show you know Canada well enough to become a citizen. It has 20 questions from the Discover Canada booklet — you need to get 15 right (75%) to pass. Think of it as proving you understand your new home country.', '[{"title":"Discover Canada","slug":"discover-canada"},{"title":"Citizenship Ceremony","slug":"citizenship-ceremony"},{"title":"Canadian Citizen","slug":"canadian-citizen"}]', 'What is the passing score on the Canadian citizenship test?', '["50% (10/20)","60% (12/20)","75% (15/20)","80% (16/20)"]', 2, 'Citizenship Test — Canadian Citizenship Glossary | PassPilot', 'What is the Canadian citizenship test? Learn about the format, passing score, topics covered, and how to prepare.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Oath of Citizenship', 'oath-of-citizenship', 'A solemn promise made by new citizens pledging loyalty to Canada and commitment to upholding its laws.', 'The Oath of Citizenship is taken at a citizenship ceremony and is the final step in becoming a Canadian citizen. In the oath, new citizens swear or affirm allegiance to the Monarch (as Canada''s head of state) and promise to faithfully observe the laws and fulfill the duties of a Canadian citizen. Once the oath is taken, the person officially becomes a Canadian citizen and receives their citizenship certificate.', 'The oath is your ''graduation speech'' into Canadian citizenship. By saying it, you''re making a formal promise to be loyal to Canada, follow its laws, and take on the responsibilities of being a citizen. After this moment, you ARE a Canadian citizen.', '[{"title":"Citizenship Ceremony","slug":"citizenship-ceremony"},{"title":"Canadian Citizen","slug":"canadian-citizen"},{"title":"Citizenship Certificate","slug":"citizenship-certificate"}]', 'To whom do new citizens swear or affirm allegiance in the Oath of Citizenship?', '["The Prime Minister","The Governor General","The Monarch (King/Queen)","The Senate"]', 2, 'Oath of Citizenship — Canadian Citizenship Glossary | PassPilot', 'What is the Canadian Oath of Citizenship? Learn the words, meaning, and why it matters for new Canadians.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Citizenship Ceremony', 'citizenship-ceremony', 'A formal event where eligible applicants take the Oath of Citizenship and officially become Canadian citizens.', 'The citizenship ceremony is organized by Immigration, Refugees and Citizenship Canada (IRCC) and is presided over by a citizenship judge or commissioner. Attendees take the Oath of Citizenship, receive their citizenship certificate, and often sing O Canada. Ceremonies may be held in person or virtually. The ceremony marks the completion of the citizenship process.', 'The citizenship ceremony is your official ''welcome to Canada'' moment. You take the oath, get your citizenship certificate, and often sing the national anthem with others who are also becoming Canadians that day. It''s a meaningful celebration of a major milestone.', '[{"title":"Oath of Citizenship","slug":"oath-of-citizenship"},{"title":"Citizenship Certificate","slug":"citizenship-certificate"},{"title":"Canadian Citizen","slug":"canadian-citizen"}]', 'What document do new citizens receive at the end of the citizenship ceremony?', '["Canadian Passport","Permanent Resident Card","Citizenship Certificate","Social Insurance Number"]', 2, 'Citizenship Ceremony — Canadian Citizenship Glossary | PassPilot', 'What happens at a Canadian citizenship ceremony? Learn about the process, what to expect, and what you receive.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Discover Canada', 'discover-canada', 'The official study guide published by IRCC that contains all the material covered in the Canadian citizenship test.', 'Discover Canada: The Rights and Responsibilities of Citizenship is the official government publication that forms the basis of all citizenship test questions. It covers Canada''s history, values, institutions, symbols, and the rights and responsibilities of citizens. The guide is available free online and in print from IRCC. All applicants are strongly encouraged to read it thoroughly before their citizenship test.', 'Discover Canada is the ''textbook'' for the citizenship test. Everything on the test comes from this one booklet. It''s like the syllabus and textbook combined — if you read it cover to cover and understand it, you have everything you need to pass.', '[{"title":"Citizenship Test","slug":"citizenship-test"},{"title":"IRCC","slug":"ircc"},{"title":"Canadian Citizen","slug":"canadian-citizen"}]', 'What is the full name of the official Canadian citizenship study guide?', '["Welcome to Canada","Discover Canada: The Rights and Responsibilities of Citizenship","Know Your Canada","The Canadian Guide to Citizenship"]', 1, 'Discover Canada — Canadian Citizenship Glossary | PassPilot', 'What is the Discover Canada guide? Learn about the official citizenship study book and how to use it to prepare for your test.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Charter of Rights and Freedoms', 'charter-of-rights-and-freedoms', 'Part of Canada''s Constitution (1982) that guarantees the fundamental rights and freedoms of all people in Canada.', 'The Canadian Charter of Rights and Freedoms is entrenched in the Constitution Act, 1982. It protects fundamental freedoms (religion, expression, assembly), democratic rights (voting), mobility rights, legal rights (fair trial), equality rights (no discrimination), and language rights. The Charter applies to government actions, not private individuals. Some rights can be limited by law under Section 1 (the ''reasonable limits'' clause) or overridden by a legislature using Section 33 (the ''notwithstanding clause'').', 'The Charter is like Canada''s list of guarantees to every person living here. It says the government cannot take away your freedom of speech, your right to a fair trial, or treat you unequally because of your race, gender, or religion. It''s the foundation of Canadian rights.', '[{"title":"Constitution Act","slug":"constitution-act"},{"title":"Rule of Law","slug":"rule-of-law"},{"title":"Equality Rights","slug":"equality-rights"}]', 'The Canadian Charter of Rights and Freedoms became part of the Constitution in which year?', '["1867","1931","1960","1982"]', 3, 'Charter of Rights and Freedoms — Canadian Citizenship Glossary | PassPilot', 'What is the Canadian Charter of Rights and Freedoms? Learn about your rights, when it was created, and what it protects.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Parliament', 'parliament', 'Canada''s national legislature, composed of the Monarch (Crown), the Senate, and the House of Commons.', 'The Parliament of Canada is the supreme legislative body at the federal level. It is bicameral, meaning it has two chambers: the elected House of Commons (338 seats) and the appointed Senate (105 seats). The Monarch (represented by the Governor General) is the formal head. Laws (bills) must pass through both chambers and receive Royal Assent before becoming law. Parliament meets in the Centre Block on Parliament Hill in Ottawa.', 'Think of Parliament as Canada''s national decision-making body. It''s like a big committee with three parts: the elected House of Commons (the main voice of the people), the Senate (a reviewing chamber), and the Crown (represented by the Governor General who gives final approval). All major national laws come from here.', '[{"title":"House of Commons","slug":"house-of-commons"},{"title":"Senate","slug":"senate"},{"title":"Prime Minister","slug":"prime-minister"}]', 'How many parts make up Canada''s Parliament?', '["Two (Senate and House of Commons)","Three (Crown, Senate, and House of Commons)","Four (Crown, Senate, House of Commons, and Supreme Court)","One (House of Commons only)"]', 1, 'Parliament — Canadian Citizenship Glossary | PassPilot', 'What is Canada''s Parliament? Learn about its three parts, how it works, and why it matters for the citizenship test.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Prime Minister', 'prime-minister', 'The head of government in Canada, typically the leader of the political party with the most seats in the House of Commons.', 'The Prime Minister (PM) is the most powerful political figure in Canada''s government. The PM leads the Cabinet, sets government policy, and commands the confidence of the House of Commons. The PM is not directly elected by all Canadians; rather, they become PM by leading the party that wins the most seats in a federal election. The PM advises the Governor General on matters such as appointments and dissolution of Parliament.', 'The Prime Minister is like the CEO of Canada''s government. While the Governor General is the official head of state representing the Monarch, the PM is the one who actually runs the country day-to-day, leads the team (Cabinet), and makes the big policy decisions.', '[{"title":"Governor General","slug":"governor-general"},{"title":"Cabinet","slug":"cabinet"},{"title":"House of Commons","slug":"house-of-commons"}]', 'How does Canada''s Prime Minister come to hold office?', '["Directly elected by all Canadians","Appointed by the Governor General for a fixed 4-year term","Leader of the party with the most seats in the House of Commons","Chosen by the Senate"]', 2, 'Prime Minister — Canadian Citizenship Glossary | PassPilot', 'What is the role of Canada''s Prime Minister? Learn how the PM is chosen and what powers they hold.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Governor General', 'governor-general', 'The representative of the Monarch in Canada, who carries out constitutional duties as head of state.', 'The Governor General (GG) is appointed by the Monarch on the advice of the Prime Minister. The GG performs duties such as reading the Speech from the Throne, granting Royal Assent to bills passed by Parliament, swearing in the Prime Minister and Cabinet, and presiding over citizenship ceremonies. In practice, the GG acts on the advice of elected officials and rarely exercises independent judgment. The office is largely ceremonial.', 'The Governor General is like the Monarch''s stand-in for day-to-day royal duties in Canada. In practice, the job is largely ceremonial — officially opening Parliament, signing laws, and representing Canada at formal events — while elected officials make the real decisions.', '[{"title":"Prime Minister","slug":"prime-minister"},{"title":"Monarch","slug":"monarch"},{"title":"Parliament","slug":"parliament"}]', 'Who does the Governor General represent in Canada?', '["The Prime Minister","The Senate","The Monarch (King or Queen)","The Supreme Court"]', 2, 'Governor General — Canadian Citizenship Glossary | PassPilot', 'What is the Governor General of Canada? Learn about the role, duties, and how they relate to the Monarch.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Multiculturalism', 'multiculturalism', 'Canada''s policy of recognizing and celebrating the cultural diversity of its population as a fundamental value.', 'Canada officially adopted multiculturalism as a policy in 1971 under Prime Minister Pierre Trudeau, and it was enshrined in the Canadian Multiculturalism Act of 1988. The policy encourages people of all cultural backgrounds to participate fully in Canadian society while preserving their cultural heritage. Canada is one of the most ethnically diverse countries in the world, with large immigrant populations in major cities like Toronto, Vancouver, and Montreal.', 'Multiculturalism means Canada doesn''t ask you to erase where you came from — it celebrates it. You can be proud of your culture, language, and traditions AND be a full Canadian. It''s like a mosaic rather than a melting pot: all the pieces keep their colour while forming a beautiful whole.', '[{"title":"Canadian Multiculturalism Act","slug":"canadian-multiculturalism-act"},{"title":"Charter of Rights and Freedoms","slug":"charter-of-rights-and-freedoms"},{"title":"Bilingualism","slug":"bilingualism"}]', 'In what year did Canada enshrine multiculturalism in federal law with the Canadian Multiculturalism Act?', '["1969","1971","1982","1988"]', 3, 'Multiculturalism — Canadian Citizenship Glossary | PassPilot', 'What is Canadian multiculturalism? Learn about this core Canadian value, the 1988 Multiculturalism Act, and what it means.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Indigenous Peoples', 'indigenous-peoples', 'The original inhabitants of Canada, comprising three distinct groups: First Nations, Métis, and Inuit.', 'Indigenous Peoples are recognized in Canada''s Constitution and include the First Nations, Métis, and Inuit. They have lived in Canada for thousands of years before European contact. Indigenous Peoples have unique rights recognized in the Constitution, including treaty rights and Aboriginal rights. Canada''s history with Indigenous Peoples includes a legacy of residential schools and other harms, which the Truth and Reconciliation Commission has addressed.', 'Indigenous Peoples are the original Canadians — they were here thousands of years before any European arrived. There are three main groups: First Nations (largest group), Métis (mixed Indigenous and European heritage), and Inuit (people of the Arctic). Their rights and culture are protected in Canada''s Constitution.', '[{"title":"First Nations","slug":"first-nations"},{"title":"Métis","slug":"metis"},{"title":"Inuit","slug":"inuit"}]', 'What are the three groups of Aboriginal peoples in Canada?', '["French, English, and Indigenous","First Nations, Métis, and Inuit","Native, Settler, and Newcomer","Algonquin, Iroquois, and Cree"]', 1, 'Indigenous Peoples — Canadian Citizenship Glossary | PassPilot', 'Who are Canada''s Indigenous Peoples? Learn about First Nations, Métis, and Inuit — their history, rights, and role in Canada.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Confederation', 'confederation', 'The political union in 1867 that created the Dominion of Canada from three British colonies.', 'Confederation refers to the creation of Canada on July 1, 1867, when the British North America Act united the Province of Canada (now Ontario and Quebec), Nova Scotia, and New Brunswick into the Dominion of Canada. Sir John A. Macdonald was instrumental in making Confederation happen and became Canada''s first Prime Minister. Canada Day (July 1) celebrates this event. After 1867, more provinces and territories joined, eventually reaching the current 10 provinces and 3 territories.', 'Confederation is like Canada''s birthday in 1867. Before that date, there were separate British colonies. The Fathers of Confederation decided to join forces and create one country called the Dominion of Canada. Today we celebrate this on July 1st — Canada Day.', '[{"title":"British North America Act","slug":"british-north-america-act"},{"title":"Canada Day","slug":"canada-day"},{"title":"John A. Macdonald","slug":"john-a-macdonald"}]', 'When did Canada become a country through Confederation?', '["July 1, 1812","July 1, 1867","July 1, 1901","July 1, 1931"]', 1, 'Confederation — Canadian Citizenship Glossary | PassPilot', 'What is Canadian Confederation? Learn about the 1867 union that created Canada and why it matters for the citizenship test.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Canada Day', 'canada-day', 'Canada''s national holiday on July 1, celebrating the anniversary of Confederation in 1867.', 'Canada Day (July 1) is Canada''s national holiday, marking the anniversary of Confederation on July 1, 1867. Canadians celebrate with fireworks, parades, concerts, and community events across the country. The largest celebrations traditionally take place on Parliament Hill in Ottawa. Canada Day was originally called Dominion Day until 1982, when it was renamed.', 'Canada Day is like Canada''s birthday party — held every July 1st to celebrate when the country was officially born in 1867. Canadians celebrate with fireworks, barbecues, and festivities. It used to be called Dominion Day, but was renamed Canada Day in 1982.', '[{"title":"Confederation","slug":"confederation"},{"title":"Remembrance Day","slug":"remembrance-day"},{"title":"National Flag","slug":"national-flag"}]', 'What does Canada Day (July 1) celebrate?', '["The signing of the Charter of Rights","The anniversary of Confederation in 1867","The end of World War II","Canada joining the United Nations"]', 1, 'Canada Day — Canadian Citizenship Glossary | PassPilot', 'What is Canada Day? Learn why July 1 is Canada''s national holiday and what it celebrates.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Official Languages', 'official-languages', 'Canada''s two official languages are English and French, protected by the Official Languages Act.', 'Canada has two official languages — English and French — as established by the Official Languages Act of 1969 and reaffirmed in the Constitution Act, 1982. This means Canadians have the right to receive federal government services in either language. New Brunswick is the only officially bilingual province. Quebec uses French as its official language. French is primarily spoken in Quebec, parts of Ontario, and New Brunswick.', 'Canada has two ''official'' languages — English and French. This means the federal government must offer services in both languages. It''s a reflection of Canada''s history: the French came first as colonists, then the British, and both languages became part of the national identity.', '[{"title":"Bilingualism","slug":"bilingualism"},{"title":"Official Languages Act","slug":"official-languages-act"},{"title":"Multiculturalism","slug":"multiculturalism"}]', 'What are Canada''s two official languages?', '["English and Spanish","English and French","French and Inuktitut","English and Indigenous languages"]', 1, 'Official Languages — Canadian Citizenship Glossary | PassPilot', 'What are Canada''s official languages? Learn about English and French and why bilingualism matters in Canada.', 'free', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Permanent Resident Card', 'permanent-resident-card', 'An identity document proving that a person has permanent resident status in Canada.', 'The Permanent Resident (PR) Card is the official document that proves a person''s PR status in Canada. It is required when returning to Canada after travelling abroad by commercial carrier. The card is valid for 5 years and must be renewed. Losing the card while abroad can make it difficult to return to Canada. It should not be confused with citizenship — the PR Card does not make someone a Canadian citizen.', 'The PR Card is basically your ID card that proves you''re a legal permanent resident of Canada. You need it to board a plane back to Canada if you travel internationally. It''s valid for 5 years and needs to be renewed — but it doesn''t make you a citizen.', '[{"title":"Permanent Resident","slug":"permanent-resident"},{"title":"Canadian Citizen","slug":"canadian-citizen"},{"title":"IRCC","slug":"ircc"}]', NULL, NULL, NULL, 'Permanent Resident Card — Canadian Citizenship Glossary | PassPilot', 'What is a Permanent Resident Card? Learn who needs one, how long it''s valid, and what it proves.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('IRCC', 'ircc', 'Immigration, Refugees and Citizenship Canada — the federal department that manages immigration and citizenship applications.', 'IRCC (Immigration, Refugees and Citizenship Canada) is the Government of Canada department responsible for processing immigration applications, refugee claims, and citizenship applications. It sets immigration targets, develops immigration policy, and administers programs like Express Entry, the Provincial Nominee Program, and the Refugee Protection Program. All citizenship applications are processed by IRCC.', 'IRCC is the government office you deal with for almost everything immigration and citizenship related — whether you''re applying for a visa, permanent residency, refugee protection, or Canadian citizenship. Think of it as the ''immigration headquarters'' of Canada.', '[{"title":"Permanent Resident","slug":"permanent-resident"},{"title":"Citizenship Test","slug":"citizenship-test"},{"title":"Express Entry","slug":"express-entry"}]', NULL, NULL, NULL, 'IRCC — Canadian Citizenship Glossary | PassPilot', 'What is IRCC? Learn about Immigration, Refugees and Citizenship Canada and its role in immigration and citizenship.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Express Entry', 'express-entry', 'Canada''s online immigration management system for selecting skilled workers for permanent residence.', 'Express Entry is a points-based federal immigration system launched in 2015 that manages applications for three programs: the Federal Skilled Worker Program, Federal Skilled Trades Program, and Canadian Experience Class. Candidates create an online profile and are ranked using the Comprehensive Ranking System (CRS). Those with the highest scores receive Invitations to Apply (ITAs) for permanent residence in regular draws.', 'Express Entry is like a competition where skilled immigrants earn points based on factors like age, education, work experience, and language skills. The highest scorers get invited to apply for permanent residency. The better your profile, the faster you can get PR.', '[{"title":"Permanent Resident","slug":"permanent-resident"},{"title":"IRCC","slug":"ircc"},{"title":"Provincial Nominee Program","slug":"provincial-nominee-program"}]', NULL, NULL, NULL, 'Express Entry — Canadian Citizenship Glossary | PassPilot', 'What is Express Entry? Learn how Canada''s points-based immigration system works for skilled workers.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Provincial Nominee Program', 'provincial-nominee-program', 'An immigration pathway where Canadian provinces and territories nominate skilled workers or international graduates for permanent residence.', 'The Provincial Nominee Program (PNP) allows provinces and territories to nominate individuals who have the skills, education, and work experience to contribute to the local economy and adapt to life in that province. Each province has its own streams and criteria. A provincial nomination significantly boosts an Express Entry CRS score (by 600 points) or can lead to a direct application for permanent residence outside Express Entry.', 'Think of the PNP as each province having its own ''guest list'' for who they want to come work there. If a province picks you, it strongly accelerates your path to permanent residency. It''s great if you already have a job offer or ties to a specific province.', '[{"title":"Express Entry","slug":"express-entry"},{"title":"Permanent Resident","slug":"permanent-resident"},{"title":"IRCC","slug":"ircc"}]', NULL, NULL, NULL, 'Provincial Nominee Program — Canadian Citizenship Glossary | PassPilot', 'What is Canada''s Provincial Nominee Program (PNP)? Learn how provinces nominate immigrants for permanent residence.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Senate', 'senate', 'The upper house of Canada''s Parliament, composed of 105 appointed senators who review legislation.', 'The Senate is the upper chamber of Canada''s Parliament. It has 105 senators appointed by the Governor General on the advice of the Prime Minister. Senators serve until the mandatory retirement age of 75. The Senate reviews and can amend legislation passed by the House of Commons, providing a ''sober second thought.'' However, the Senate cannot initiate money bills and rarely defeats legislation passed by the elected House.', 'The Senate is like the ''second opinion'' chamber in Parliament. After elected MPs in the House of Commons pass a law, it goes to the Senate for review. Senators aren''t elected — they''re appointed — and they''re supposed to catch problems in laws that MPs may have missed.', '[{"title":"Parliament","slug":"parliament"},{"title":"House of Commons","slug":"house-of-commons"},{"title":"Governor General","slug":"governor-general"}]', 'How many senators are there in Canada''s Senate?', '["69","85","105","338"]', 2, 'Senate — Canadian Citizenship Glossary | PassPilot', 'What is the Canadian Senate? Learn about its 105 senators, their role, and how they fit into Parliament.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('House of Commons', 'house-of-commons', 'The elected lower chamber of Canada''s Parliament with 338 Members of Parliament (MPs).', 'The House of Commons is the primary elected chamber of Parliament, currently with 338 seats. Members of Parliament (MPs) are elected in federal elections using a first-past-the-post system. The party with the most seats typically forms the government, and its leader becomes Prime Minister. The House of Commons is where most legislation originates and debates take place. The Speaker of the House presides over debates.', 'The House of Commons is where Canada''s elected representatives (MPs) debate and pass laws. It''s the more powerful of Parliament''s two chambers because its members are directly elected by Canadians. More seats = more power — the party with the most seats forms the government.', '[{"title":"Parliament","slug":"parliament"},{"title":"Senate","slug":"senate"},{"title":"Member of Parliament","slug":"member-of-parliament"}]', 'How many seats are in Canada''s House of Commons?', '["105","265","308","338"]', 3, 'House of Commons — Canadian Citizenship Glossary | PassPilot', 'What is Canada''s House of Commons? Learn about the 338 MPs, how they''re elected, and the role they play.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('First Nations', 'first-nations', 'One of the three groups of Indigenous Peoples in Canada, representing hundreds of distinct nations, cultures, and languages.', 'First Nations are the largest group of Indigenous Peoples in Canada, comprising over 630 distinct communities with their own governments, cultures, and languages. First Nations peoples have lived in Canada for thousands of years and have rights recognized in Canada''s Constitution, including treaty rights negotiated with the Crown. Many First Nations communities face ongoing socioeconomic challenges as a result of colonialism and historical government policies.', 'First Nations are one of Canada''s three Indigenous groups — the others are Métis and Inuit. There are over 630 different First Nations communities, each with its own culture, language, and government. They were the first people to live in what is now Canada, thousands of years before Europeans arrived.', '[{"title":"Indigenous Peoples","slug":"indigenous-peoples"},{"title":"Métis","slug":"metis"},{"title":"Inuit","slug":"inuit"}]', NULL, NULL, NULL, 'First Nations — Canadian Citizenship Glossary | PassPilot', 'Who are Canada''s First Nations? Learn about their history, rights, and role in Canadian society.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Métis', 'metis', 'Indigenous people of mixed European and First Nations heritage, forming a distinct cultural and political identity in Canada.', 'The Métis are one of the three recognized Aboriginal peoples in Canada''s Constitution. Their origins lie in the 18th and early 19th centuries, when French-Canadian and Scottish fur traders formed families with First Nations women. The Métis developed a distinct culture, language (Michif), and sense of nationhood centred in the Red River area of Manitoba. Louis Riel, a Métis leader, led two resistance movements in 1869–70 and 1885.', 'The Métis are a unique group — they have both Indigenous and European (mainly French) ancestry, and they developed their own distinct identity, culture, and even language (called Michif). They''re not simply ''mixed'' people; they formed their own nation with their own traditions and rights.', '[{"title":"Indigenous Peoples","slug":"indigenous-peoples"},{"title":"First Nations","slug":"first-nations"},{"title":"Louis Riel","slug":"louis-riel"}]', NULL, NULL, NULL, 'Métis — Canadian Citizenship Glossary | PassPilot', 'Who are the Métis people of Canada? Learn about their unique heritage, history, and recognition in the Constitution.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Inuit', 'inuit', 'Indigenous peoples of Canada''s Arctic regions, primarily living in Nunavut, Northwest Territories, Quebec (Nunavik), and Labrador.', 'The Inuit are one of the three groups of Aboriginal peoples recognized in Canada''s Constitution. They have inhabited the Arctic regions of Canada for thousands of years and have a unique cultural identity centred on Arctic living. Inuit Nunangat (the Inuit homeland) covers about 35% of Canada''s land area. The Inuit language family includes Inuktitut and Inuinnaqtun. In 1999, Nunavut was created as a territory largely in response to Inuit land claims.', 'The Inuit are Indigenous peoples of Canada''s far north — the Arctic regions. They have lived there for over 4,000 years, developing remarkable skills for surviving in one of the harshest environments on Earth. Nunavut, Canada''s newest territory (created in 1999), was established largely for the Inuit people.', '[{"title":"Indigenous Peoples","slug":"indigenous-peoples"},{"title":"First Nations","slug":"first-nations"},{"title":"Métis","slug":"metis"}]', NULL, NULL, NULL, 'Inuit — Canadian Citizenship Glossary | PassPilot', 'Who are the Inuit of Canada? Learn about Canada''s Arctic Indigenous people, their culture, and Nunavut territory.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('National Flag', 'national-flag', 'Canada''s flag features a red maple leaf on a white background with red borders, adopted in 1965.', 'Canada''s national flag — the Maple Leaf flag — was officially adopted on February 15, 1965, replacing the old Canadian Red Ensign. It features two red vertical bars on either side of a white square containing a stylized 11-pointed red maple leaf. The red and white colours represent Canada''s connection to England and France. February 15 is celebrated as National Flag of Canada Day.', 'Canada''s flag is one of the most recognizable in the world — a red maple leaf on white, framed by red. The maple leaf has been a Canadian symbol since the 1700s. The flag was only officially adopted in 1965; before that, Canada used a British-style flag with the Union Jack.', '[{"title":"Canada Day","slug":"canada-day"},{"title":"National Anthem","slug":"national-anthem"},{"title":"Maple Leaf","slug":"maple-leaf"}]', 'In what year was Canada''s current national flag (the Maple Leaf) officially adopted?', '["1867","1931","1965","1982"]', 2, 'National Flag — Canadian Citizenship Glossary | PassPilot', 'What does Canada''s flag look like? Learn when it was adopted and what the red maple leaf represents.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('National Anthem', 'national-anthem', 'O Canada is Canada''s national anthem, officially adopted in 1980.', 'O Canada is Canada''s national anthem. It was composed in 1880 by Calixa Lavallée with French lyrics by Adolphe-Basile Routhier. An English version was written in 1908 by Robert Stanley Weir. O Canada was officially proclaimed Canada''s national anthem on July 1, 1980. It is sung at official events, sporting competitions, and citizenship ceremonies. The lyrics were amended in 2018 to make them gender-neutral (''in all of us command'' instead of ''in all thy sons command'').', 'O Canada is the song that represents Canada — like a country''s musical signature. It was written in 1880 in French, then an English version was added. It became the official national anthem in 1980. You''ll hear it sung at citizenship ceremonies, sporting events, and national celebrations.', '[{"title":"Canada Day","slug":"canada-day"},{"title":"National Flag","slug":"national-flag"},{"title":"Citizenship Ceremony","slug":"citizenship-ceremony"}]', 'In what year did O Canada officially become Canada''s national anthem?', '["1867","1931","1967","1980"]', 3, 'National Anthem — Canadian Citizenship Glossary | PassPilot', 'What is Canada''s national anthem? Learn about O Canada — its history, lyrics, and when it became official.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Treaty Rights', 'treaty-rights', 'Rights and obligations agreed upon in treaties between the Crown and Indigenous peoples, recognized in Canada''s Constitution.', 'Treaties are legally binding agreements made between the Crown (representing the Canadian government) and Indigenous peoples. They often involve land rights, resource rights, and obligations for both parties. Historic treaties (such as the numbered treaties signed between 1871 and 1921) covered much of Canada. Section 35 of the Constitution Act, 1982 recognizes and affirms existing Aboriginal and treaty rights. Modern treaties (comprehensive land claims) continue to be negotiated today.', 'Treaty rights are the promises the Canadian government made to Indigenous peoples in formal agreements called treaties. These are serious legal contracts — like business deals between nations — and they''re protected in Canada''s Constitution. They often involve land use, hunting rights, and government obligations to Indigenous communities.', '[{"title":"Indigenous Peoples","slug":"indigenous-peoples"},{"title":"First Nations","slug":"first-nations"},{"title":"Constitution Act","slug":"constitution-act"}]', NULL, NULL, NULL, 'Treaty Rights — Canadian Citizenship Glossary | PassPilot', 'What are treaty rights in Canada? Learn about agreements between the Crown and Indigenous peoples and their constitutional protection.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Refugee', 'refugee', 'A person who has fled their country due to persecution, war, or violence and is seeking protection abroad.', 'Under the 1951 UN Refugee Convention (to which Canada is a signatory), a refugee is a person who is outside their country of nationality and cannot return due to a well-founded fear of persecution based on race, religion, nationality, political opinion, or membership in a particular social group. Canada has a robust refugee protection system, accepting government-assisted refugees (GARs), privately sponsored refugees (PSRs), and refugee protection claimants (inland claimants).', 'A refugee is someone who had to flee their home country because they were in danger — maybe because of their religion, race, or political beliefs. Canada is known worldwide for welcoming refugees and giving them protection. Once accepted, refugees can eventually become permanent residents and then citizens.', '[{"title":"IRCC","slug":"ircc"},{"title":"Permanent Resident","slug":"permanent-resident"},{"title":"Asylum Seeker","slug":"asylum-seeker"}]', NULL, NULL, NULL, 'Refugee — Canadian Citizenship Glossary | PassPilot', 'What is a refugee in Canada? Learn about Canada''s refugee protection system and how it differs from immigration.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Medicare', 'medicare', 'Canada''s publicly funded universal healthcare system that provides medically necessary services to all residents.', 'Medicare is Canada''s publicly funded universal health care system, established under the Canada Health Act (1984). Each province and territory administers its own health insurance plan, funded jointly by provincial and federal governments. Covered services include hospital care and physician services. Residents receive a provincial health card (such as OHIP in Ontario) to access these services. Dental care, prescription drugs, and other services may require additional private insurance.', 'Medicare means that in Canada, if you need to see a doctor or go to a hospital, you don''t pay directly — the government covers it. Every province runs its own version of this system. It''s one of the things Canadians are most proud of. You just need your provincial health card to access most medical services.', '[{"title":"Social Insurance Number","slug":"social-insurance-number"},{"title":"Health Card","slug":"health-card"},{"title":"Canada Health Act","slug":"canada-health-act"}]', NULL, NULL, NULL, 'Medicare — Canadian Citizenship Glossary | PassPilot', 'What is Canada''s Medicare? Learn about universal healthcare, the Canada Health Act, and how to access medical services.', 'login', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Social Insurance Number', 'social-insurance-number', 'A unique 9-digit number issued to individuals in Canada for tax reporting and access to government benefits.', 'A Social Insurance Number (SIN) is required to work in Canada, file taxes, and access federal programs like the Canada Pension Plan and Employment Insurance. It is issued by Service Canada. The SIN is confidential and should only be shared with employers, financial institutions, and government agencies when legally required. Permanent residents and authorized foreign workers are also eligible for a SIN.', 'Your SIN is like your personal ID number for Canada''s financial and government systems. You need it for every job you get, filing your taxes, and accessing government benefits. Keep it private — sharing it carelessly can lead to identity theft.', '[{"title":"Medicare","slug":"medicare"},{"title":"Service Canada","slug":"service-canada"},{"title":"Employment Insurance","slug":"employment-insurance"}]', NULL, NULL, NULL, 'Social Insurance Number — Canadian Citizenship Glossary | PassPilot', 'What is a Social Insurance Number (SIN) in Canada? Learn why you need one and how to protect it.', 'login', 'active');
