INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Famous Five', 'famous-five', 'Five Canadian women who won the Persons Case in 1929, establishing that women are ''persons'' under the law and eligible for the Senate.', 'The Famous Five were Emily Murphy, Nellie McClung, Irene Parlby, Louise McKinney, and Henrietta Muir Edwards — all from Alberta. In 1927 they petitioned the Supreme Court of Canada to ask whether women were ''persons'' under the British North America Act and therefore qualified to serve in the Senate. The Supreme Court ruled that women were NOT persons. The Famous Five appealed to the British Privy Council, which overturned the ruling on October 18, 1929, declaring that women are indeed persons. This landmark decision was a defining moment in the fight for women''s equality in Canada.

The Famous Five are commemorated with statues on Parliament Hill in Ottawa and on Olympic Plaza in Calgary. Emily Murphy was also the first female magistrate in the British Empire. October 18 is now recognized as Persons Day in Canada.', 'Before 1929, the law said women weren''t ''persons'' — which meant they couldn''t be appointed to the Senate or many government positions. The Famous Five were five brave women from Alberta who fought this all the way to the highest court and won. Their victory opened the doors of full legal equality for all Canadian women.', '[{"title":"Charter of Rights and Freedoms","slug":"charter-of-rights-and-freedoms"},{"title":"Equality Rights","slug":"equality-rights"},{"title":"Senate","slug":"senate"}]', 'What right did the Famous Five win for Canadian women in the 1929 Persons Case?', '["The right to vote in federal elections","The right to be recognized as ''persons'' and serve in the Senate","The right to own property independently","The right to equal pay"]', 1, 'Famous Five — Canadian Citizenship Glossary | PassPilot', 'Who were the Famous Five? Learn about the women who won the Persons Case in 1929 and changed Canadian history.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Battle of the Plains of Abraham', 'battle-of-the-plains-of-abraham', 'A 1759 battle in Quebec City where British forces defeated the French, leading to British control of New France and shaping Canada''s bilingual character.', 'The Battle of the Plains of Abraham (September 13, 1759) was a pivotal engagement during the Seven Years'' War. British General James Wolfe led his forces up the cliffs of Quebec City in a surprise night attack, defeating the French forces commanded by the Marquis de Montcalm. Both Wolfe and Montcalm died in the battle. The British victory led to the fall of Quebec City and, ultimately, the surrender of New France to Britain through the Treaty of Paris (1763).

This battle fundamentally shaped Canada''s future. Britain now controlled a large French-speaking Catholic population. Rather than attempting to assimilate the Canadiens (French Canadians), Britain passed the Quebec Act of 1774, which protected French civil law, the French language, and the Catholic Church. This accommodation created the foundation for Canada''s bilingual, bicultural identity that persists to this day.', 'Think of this battle as the moment Canada''s bilingual identity was decided. When Britain won in 1759, they had to figure out what to do with 70,000 French-speaking Canadians. Instead of forcing them to become English, Britain let them keep their language, religion, and laws. That tolerance is why Canada is bilingual today.', '[{"title":"New France","slug":"new-france"},{"title":"Quebec Act 1774","slug":"quebec-act-1774"},{"title":"Official Languages","slug":"official-languages"}]', 'What major consequence resulted from the British victory at the Battle of the Plains of Abraham (1759)?', '["Canada became a republic","Britain took control of New France, shaping Canada''s bilingual future","France permanently left North America","Canada''s Indigenous peoples lost all treaty rights"]', 1, 'Battle of the Plains of Abraham — Canadian Citizenship Glossary | PassPilot', 'What was the Battle of the Plains of Abraham? Learn how this 1759 battle shaped Canada''s bilingual character.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Order of Canada', 'order-of-canada', 'Canada''s highest civilian honour, awarded to Canadians who have made extraordinary contributions to the country.', 'The Order of Canada was established in 1967 during Canada''s Centennial year. It is the cornerstone of Canada''s honours system and recognizes outstanding achievement, dedication to community, and service to Canada. There are three levels: Companion (the highest, for national or international contributions), Officer (for contributions at the national level), and Member (for outstanding service at the local or regional level). Appointments are made by the Governor General on the recommendation of an Advisory Council.

Recipients include scientists, artists, athletes, public servants, and community leaders. Well-known recipients have included Terry Fox (Order of Canada), Wayne Gretzky (Companion), and Céline Dion. The motto of the Order of Canada is ''Desiderantes meliorem patriam'' — Latin for ''They desire a better country.''', 'The Order of Canada is like Canada''s ''thank you medal'' for extraordinary citizens. If you''ve done something truly remarkable for Canada — in science, arts, sports, community service — the government can recognize you with this honour. There are three levels, with Companion being the highest, like the A+ of Canadian recognition.', '[{"title":"Governor General","slug":"governor-general"},{"title":"Citizenship Ceremony","slug":"citizenship-ceremony"},{"title":"Canadian Citizen","slug":"canadian-citizen"}]', 'What is the highest civilian honour that can be awarded to a Canadian?', '["The Victoria Cross","The Order of Canada (Companion level)","The Medal of Bravery","The Meritorious Service Medal"]', 1, 'Order of Canada — Canadian Citizenship Glossary | PassPilot', 'What is the Order of Canada? Learn about Canada''s highest civilian honour and how it is awarded.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Chinese Canadian History', 'chinese-canadian-history', 'The history of Chinese immigration to Canada, marked by significant contributions (CPR construction) and systemic discrimination (Chinese Head Tax and Exclusion Act).', 'Chinese immigrants began arriving in Canada in large numbers during the 1858 Gold Rush and were crucial to building the Canadian Pacific Railway (1881–1885). Despite this contribution, the federal government imposed a Chinese Head Tax in 1885 — a fee of $50 (later raised to $500) charged only to Chinese immigrants. Between 1885 and 1923, the government collected approximately $23 million in head taxes. In 1923, the Chinese Immigration Act (called the Exclusion Act) virtually banned all Chinese immigration.

The Exclusion Act was repealed in 1947. In 2006, Prime Minister Stephen Harper issued a formal apology to Chinese Canadians for the head tax. The Chinese Canadian community has made enormous contributions to Canadian culture, business, cuisine, and public life. Today, Chinese Canadians are one of the largest ethnic communities in Canada, concentrated in Vancouver and Toronto.', 'Chinese Canadians helped build Canada''s railway, which united the country from coast to coast — and then were punished for it with discriminatory taxes and bans. This dark chapter is an important reminder of Canada''s imperfections and why equality rights in the Charter matter so much today.', '[{"title":"Multiculturalism","slug":"multiculturalism"},{"title":"Charter of Rights and Freedoms","slug":"charter-of-rights-and-freedoms"},{"title":"Canadian Pacific Railway","slug":"canadian-pacific-railway"}]', 'What was the Chinese Head Tax?', '["A property tax on Chinese-owned businesses","A fee charged exclusively to Chinese immigrants entering Canada, from 1885 to 1923","A tax on all Asian goods imported into Canada","An annual fee paid by all visible minorities"]', 1, 'Chinese Canadian History — Canadian Citizenship Glossary | PassPilot', 'Learn about Chinese Canadian history — contributions, the Head Tax, and the journey to equality in Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Canadian Pacific Railway', 'canadian-pacific-railway', 'Canada''s first transcontinental railway, completed in 1885, which physically united Canada from the Atlantic to the Pacific and was central to Confederation.', 'The Canadian Pacific Railway (CPR) was a condition of British Columbia joining Confederation in 1871 — BC demanded a rail link to the east. The CPR was built between 1881 and 1885 under the leadership of William Van Horne and was financed through a combination of government subsidies and private investment. The railway was completed when Donald Smith drove the famous ''last spike'' at Craigellachie, British Columbia, on November 7, 1885.

The CPR''s construction relied heavily on approximately 15,000 Chinese workers who did the most dangerous work blasting through the Rocky Mountains and Selkirk Mountains. The CPR opened up western Canada to settlement, enabled the transport of prairie wheat to markets, and made it possible for the federal government to suppress the Northwest Rebellion of 1885. It remains one of the most significant nation-building projects in Canadian history.', 'The CPR was basically the glue that held early Canada together. Without a railway connecting east and west, BC would have had no reason to join Confederation. Imagine Canada ending at Manitoba — the CPR made Canada truly ''coast to coast.'' It was dangerous, expensive, and only possible with the labour of thousands of Chinese workers who never received proper recognition.', '[{"title":"Confederation","slug":"confederation"},{"title":"Chinese Canadian History","slug":"chinese-canadian-history"},{"title":"John A. Macdonald","slug":"john-a-macdonald"}]', 'What was the significance of completing the Canadian Pacific Railway in 1885?', '["It replaced the St. Lawrence River as the main trade route","It physically united Canada from the Atlantic to the Pacific, fulfilling a Confederation promise to BC","It was the first privately funded infrastructure project in Canada","It allowed Canada to export oil to the United States"]', 1, 'Canadian Pacific Railway — Canadian Citizenship Glossary | PassPilot', 'What was the Canadian Pacific Railway? Learn how the CPR united Canada and its role in Confederation and history.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Persons Case', 'persons-case', 'The 1929 ruling by the British Privy Council declaring that women are ''persons'' under Canadian law, making them eligible for Senate appointment.', 'The Persons Case (formally Edwards v. Canada (Attorney General)) was a constitutional challenge brought by the Famous Five — five Alberta women. Section 24 of the British North America Act referred to ''qualified persons'' being eligible for Senate appointment. The question was whether ''persons'' included women. In 1928, the Supreme Court of Canada ruled unanimously that ''persons'' did NOT include women, as women could not vote or hold public office when the BNA Act was drafted in 1867.

The Famous Five appealed to the Judicial Committee of the Privy Council in London, which was Canada''s highest court of appeal at the time. On October 18, 1929, the Privy Council overruled the Supreme Court, declaring that women ARE ''persons'' and can be appointed to the Senate. The decision stated that the BNA Act was ''a living tree capable of growth and expansion within its natural limits.'' October 18 is celebrated as Persons Day in Canada.', 'Before 1929, the law didn''t consider women to be ''persons'' — which sounds shocking today. The Supreme Court of Canada actually ruled against women. It took five determined women from Alberta to appeal to a higher court in Britain to finally get women recognized as full persons under the law. Their win is why we can talk about ''living tree'' interpretation of the Constitution today.', '[{"title":"Famous Five","slug":"famous-five"},{"title":"Charter of Rights and Freedoms","slug":"charter-of-rights-and-freedoms"},{"title":"Senate","slug":"senate"}]', 'What did the 1929 Persons Case establish in Canada?', '["Women''s right to vote in federal elections","That women are legally ''persons'' and eligible for Senate appointment","Equal pay for equal work","Women''s right to own property"]', 1, 'Persons Case — Canadian Citizenship Glossary | PassPilot', 'What was the Persons Case of 1929? Learn how the Famous Five won legal personhood for women in Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Japanese Canadian Internment', 'japanese-canadian-internment', 'The forced relocation and internment of approximately 22,000 Japanese Canadians during World War II, considered one of Canada''s most shameful acts.', 'Following Japan''s attack on Pearl Harbor (December 7, 1941), the Canadian government — fearing espionage — ordered the forced removal of all people of Japanese origin living within 100 miles of the BC coast. Approximately 22,000 Japanese Canadians (including Canadian-born citizens) were relocated to interior BC, Alberta, Manitoba, and Ontario. Their homes, businesses, fishing boats, and property were seized and sold. Many were sent to work camps or internment sites in isolated locations.

The internment continued until 1949, four years after the war ended. In 1988, Prime Minister Brian Mulroney issued a formal apology to Japanese Canadians and the government provided $21,000 in compensation to surviving internees. The internment is studied today as an example of wartime racism and a reminder of why the Charter of Rights and Freedoms — and its protections against discrimination — are so important.', 'During WWII, the Canadian government was so afraid of Japanese Canadians being spies that they took away 22,000 people''s homes, businesses, and freedom — even though most were Canadian citizens. It was wrong then, and the government apologized decades later. This is why Canada''s Charter says the government CANNOT discriminate based on national or ethnic origin.', '[{"title":"Charter of Rights and Freedoms","slug":"charter-of-rights-and-freedoms"},{"title":"Equality Rights","slug":"equality-rights"},{"title":"World War II","slug":"world-war-ii"}]', 'In what year did Canada officially apologize for the Japanese Canadian internment during WWII?', '["1945","1967","1988","2001"]', 2, 'Japanese Canadian Internment — Canadian Citizenship Glossary | PassPilot', 'Learn about the Japanese Canadian internment of WWII — what happened, why, and Canada''s formal apology in 1988.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Underground Railroad', 'underground-railroad', 'A network of secret routes and safe houses that helped enslaved people from the United States escape to freedom in Canada in the 1800s.', 'The Underground Railroad was not a literal railroad but a secret network of routes, safe houses, and people who helped enslaved African Americans escape from slave states in the US to free states and Canada. Canada, where slavery had been abolished in 1833 under the British Empire, was a destination for freedom-seekers. It is estimated that between 30,000 and 40,000 enslaved people escaped to Canada via the Underground Railroad, primarily between the 1850s and the American Civil War.

Key figures included Harriet Tubman, who made 19 trips and guided 300 people to freedom, spending significant time in St. Catharines, Ontario. Freedom-seekers settled in communities across Ontario, Nova Scotia, and elsewhere in Canada. The community of Buxton (near Chatham, Ontario) and other Black communities became thriving settlements. After the American Civil War ended slavery in the US (1865), many returned south, but thousands remained and their descendants are part of Canada''s African-Canadian communities today.', 'The Underground Railroad was like a secret network of brave people helping enslaved Americans escape to freedom in Canada. Because Britain abolished slavery before the US did, Canada was a destination for freedom. Thousands of people risked everything to escape to Canada, and many communities of their descendants still exist today.', '[{"title":"Black Loyalists","slug":"black-loyalists"},{"title":"Multiculturalism","slug":"multiculturalism"},{"title":"Equality Rights","slug":"equality-rights"}]', 'Why was Canada a destination for people escaping via the Underground Railroad in the 1800s?', '["Canada had no border controls at the time","Slavery had been abolished in Canada (as part of the British Empire) since 1833","Canada offered land grants to all arrivals","The US government could not pursue escaped people into Canada"]', 1, 'Underground Railroad — Canadian Citizenship Glossary | PassPilot', 'What was the Underground Railroad? Learn how Canada became a destination for freedom-seekers from the United States.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Black Loyalists', 'black-loyalists', 'Black Americans who supported Britain during the American Revolution and came to Canada (mainly Nova Scotia and New Brunswick) after 1783 seeking freedom.', 'Black Loyalists were Black Americans — many of whom had been enslaved — who sided with the British during the American Revolution (1775–1783), often in exchange for promises of freedom. When Britain lost the war, approximately 3,500 Black Loyalists came to Nova Scotia and New Brunswick in 1783 as part of the broader Loyalist migration. They were among the first Black settlers in Atlantic Canada.

Despite their service, Black Loyalists faced severe discrimination. They received smaller land grants than white Loyalists, and many were refused grants altogether. In 1792, about 1,200 Black Loyalists chose to leave for Sierra Leone in West Africa, frustrated by discrimination. Those who remained, along with later arrivals, formed the foundation of African-Nova Scotian communities that persist today. Their history is an important part of Canada''s diverse cultural heritage.', 'Black Loyalists were Black people who came to Canada after the American Revolution because Britain promised them freedom. Canada was supposed to be a fresh start — but they faced discrimination even here. Their story is important because it shows that Canada''s diversity goes back more than 200 years, and that the fight for true equality has been long.', '[{"title":"Underground Railroad","slug":"underground-railroad"},{"title":"Loyalists","slug":"loyalists"},{"title":"Atlantic Canada","slug":"atlantic-canada"}]', 'When did Black Loyalists first arrive in large numbers in Atlantic Canada?', '["1759 after the Battle of the Plains of Abraham","1783 following the American Revolution","1833 when slavery was abolished in Britain","1865 after the American Civil War"]', 1, 'Black Loyalists — Canadian Citizenship Glossary | PassPilot', 'Who were the Black Loyalists? Learn about Canada''s earliest Black settlers in Atlantic Canada and their history.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Northwest Rebellion', 'northwest-rebellion', 'The 1885 armed resistance led by Louis Riel and the Métis in Saskatchewan against the Canadian government''s failure to address Métis land rights.', 'The Northwest Rebellion (also called the North-West Resistance) was an armed conflict in 1885 in what is now Saskatchewan. Led by Louis Riel and Métis military leader Gabriel Dumont, the Métis took up arms after years of petitioning the federal government about their land rights and the rights of Indigenous peoples. The conflict included battles at Duck Lake, Fish Creek, and Batoche.

The Canadian government used the newly completed Canadian Pacific Railway to quickly transport troops west to suppress the rebellion. Riel surrendered in May 1885 after the fall of Batoche and was tried for high treason. Despite appeals for clemency, he was executed by hanging on November 16, 1885, in Regina. Riel''s execution deeply divided Canadians — particularly French Canadians, who saw him as a martyr — and had lasting political consequences, contributing to the rise of Wilfrid Laurier and the Liberal Party.', 'The Northwest Rebellion was Louis Riel''s second and final resistance. The Métis had been ignored by Ottawa for years — their land was being taken, their rights denied. When they finally fought back in 1885, the new railway allowed Canada to crush the rebellion in weeks. Riel''s execution turned him into a national symbol: hero to French Canadians, traitor to some English Canadians.', '[{"title":"Louis Riel","slug":"louis-riel"},{"title":"Métis","slug":"metis"},{"title":"Canadian Pacific Railway","slug":"canadian-pacific-railway"}]', 'What was the outcome of the 1885 Northwest Rebellion for Louis Riel?', '["He was pardoned and appointed to the Senate","He was convicted of high treason and executed by hanging","He fled to the United States and lived in exile","He was imprisoned but later released and given a land grant"]', 1, 'Northwest Rebellion — Canadian Citizenship Glossary | PassPilot', 'What was the 1885 Northwest Rebellion? Learn about Louis Riel, the Métis resistance, and its impact on Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Durham Report', 'durham-report', 'An 1839 report by Lord Durham recommending responsible government and the union of Upper and Lower Canada after the Rebellions of 1837–38.', 'After the Rebellions of 1837–38 in Upper Canada (Ontario) and Lower Canada (Quebec), Britain sent Lord Durham to investigate. His 1839 report, often called ''the report that launched a thousand ships,'' made two key recommendations: (1) unite Upper and Lower Canada under a single legislature to assimilate French Canadians into English culture; and (2) grant ''responsible government'' — meaning the elected assembly rather than an appointed governor would control domestic affairs.

The Act of Union of 1840 implemented the union, creating the Province of Canada. Responsible government was achieved in 1848–49. Durham''s report significantly underestimated French Canadian resilience — rather than assimilating, French Canadian culture and language thrived and became an enduring pillar of Canadian identity. The achievement of responsible government was a critical step toward Confederation in 1867.', 'Lord Durham''s report was like a troubleshooter''s assessment after Canada''s failed rebellions of 1837. He recommended letting Canadians govern themselves (responsible government) and uniting French and English Canada. His plan to assimilate French Canadians failed spectacularly — French Canada didn''t disappear. But responsible government succeeded and paved the way to Confederation.', '[{"title":"Confederation","slug":"confederation"},{"title":"Responsible Government","slug":"responsible-government"},{"title":"Official Languages","slug":"official-languages"}]', 'What was Lord Durham''s most significant recommendation in his 1839 report?', '["Granting independence to Canada immediately","Granting responsible government and uniting Upper and Lower Canada","Allowing Quebec to separate from British control","Establishing a Senate to represent the provinces"]', 1, 'Durham Report — Canadian Citizenship Glossary | PassPilot', 'What was the Durham Report? Learn about the 1839 report that led to responsible government and Confederation in Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Conscription Crisis WWI', 'conscription-crisis-wwi', 'A political crisis in 1917 caused by Prime Minister Borden''s Military Service Act, which imposed mandatory military service and deeply divided English and French Canadians.', 'By 1917, Canada''s volunteer army was suffering massive casualties on the Western Front and enlistment rates had fallen. Prime Minister Robert Borden introduced the Military Service Act (conscription) to maintain troop numbers. The act was bitterly opposed by French Canadians, who felt little connection to the British Empire''s war, and by many farmers, immigrants, and labour groups.

The resulting election of 1917 — the ''Khaki Election'' — was one of the most divisive in Canadian history. Borden''s Union Government (a coalition of Conservatives and English-speaking Liberals) won largely on an English-Canadian vote. Quebec voted overwhelmingly against conscription. Anti-conscription riots occurred in Quebec City in April 1918. The conscription crisis deepened French-English tensions that persisted for decades. Only about 24,000 conscripts actually served in combat before the war ended in November 1918.', 'The WWI conscription crisis was the moment Canada almost broke apart along linguistic lines. French Canadians didn''t see Britain''s war as their war — why should they die for an Empire they didn''t identify with? English Canadians thought duty demanded sacrifice. The bitter division this created echoed for generations and is why French-English relations remain a central theme in Canadian history.', '[{"title":"World War I","slug":"world-war-i"},{"title":"Bilingualism","slug":"bilingualism"},{"title":"Wilfrid Laurier","slug":"wilfrid-laurier"}]', 'Why did the 1917 conscription crisis in Canada cause such a deep French-English divide?', '["French Canadians could not legally serve in the military","Many French Canadians felt no loyalty to the British Empire and opposed being forced to fight in its war","Quebec was constitutionally exempt from federal military laws","French Canadians supported Germany in WWI"]', 1, 'Conscription Crisis WWI — Canadian Citizenship Glossary | PassPilot', 'What was the WWI conscription crisis in Canada? Learn how the 1917 Military Service Act divided French and English Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Quebec Referendum 1980', 'quebec-referendum-1980', 'A 1980 provincial vote in which Quebec voters rejected, by 60% to 40%, giving the government a mandate to negotiate sovereignty-association with Canada.', 'On May 20, 1980, Quebec held a referendum on sovereignty-association — a proposal by the Parti Québécois government of Premier René Lévesque for Quebec to become politically sovereign (independent) while maintaining economic association with Canada. The question asked voters to give the government a mandate to negotiate such an arrangement. Prime Minister Pierre Trudeau campaigned vigorously for the ''No'' side.

The ''No'' side won with 59.56% of the vote. Trudeau had promised Quebecers that a ''No'' vote would lead to constitutional renewal, which contributed to the patriation of the Constitution in 1982 — though Quebec never signed the Constitution Act, 1982. The referendum revealed the deep currents of Quebec nationalism that would resurface in a second referendum in 1995.', 'In 1980, Quebecers voted on whether to start negotiations to separate from Canada while keeping economic ties. Most said no (60%), but the vote showed that nearly half of Quebec''s population wanted something fundamentally different. PM Trudeau promised constitutional changes if they voted no, which is part of why Canada got its Charter of Rights in 1982.', '[{"title":"Quebec Referendum 1995","slug":"quebec-referendum-1995"},{"title":"Quiet Revolution","slug":"quiet-revolution"},{"title":"Patriation of the Constitution","slug":"patriation-of-the-constitution"}]', 'What was the result of the 1980 Quebec sovereignty referendum?', '["The ''Yes'' side won and Quebec began separation negotiations","The ''No'' side won with approximately 60% of the vote","The vote was tied and a second referendum was immediately held","The federal government refused to hold the referendum"]', 1, 'Quebec Referendum 1980 — Canadian Citizenship Glossary | PassPilot', 'What was the 1980 Quebec Referendum? Learn about the vote on sovereignty-association and its impact on Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Quebec Referendum 1995', 'quebec-referendum-1995', 'A near-miss 1995 vote in which Quebec voters rejected independence from Canada by only 50.58% to 49.42% — the closest vote in Canadian democratic history.', 'On October 30, 1995, Quebec held its second referendum on independence. The ''Yes'' side, led by PQ Premier Jacques Parizeau and Bloc Québécois leader Lucien Bouchard, proposed that Quebec become an independent country. The campaign was extremely close and emotionally charged. The ''No'' side, led by Quebec Liberal leader Daniel Johnson and supported by Prime Minister Jean Chrétien, narrowly won with 50.58% of the vote — a margin of only about 50,000 votes out of nearly 5 million cast.

The result shocked Canadians. The federal government responded with the Clarity Act (2000), which established that any future Quebec independence referendum must ask a clear question and achieve a clear majority. The 1995 referendum remains the closest Canada has come to breaking apart. It fundamentally changed how Ottawa approached Quebec''s place in Confederation and reinforced discussions about recognition of Quebec''s distinct society.', 'The 1995 Quebec referendum was the most nerve-wracking moment in modern Canadian history. Less than 1% of votes separated Canada staying together from potentially breaking up. 49.42% of Quebec voters said YES to independence. The narrowness of the result forced Canada to take Quebec''s concerns much more seriously and to pass clearer rules about how any future separatism vote would work.', '[{"title":"Quebec Referendum 1980","slug":"quebec-referendum-1980"},{"title":"Quiet Revolution","slug":"quiet-revolution"},{"title":"Bilingualism","slug":"bilingualism"}]', 'By what margin did the ''No'' side win the 1995 Quebec independence referendum?', '["By approximately 20 percentage points (60% to 40%)","By approximately 10 percentage points (55% to 45%)","By less than 1 percentage point (50.58% to 49.42%)","By exactly 5 percentage points (52.5% to 47.5%)"]', 2, 'Quebec Referendum 1995 — Canadian Citizenship Glossary | PassPilot', 'What was the 1995 Quebec Referendum? Learn about the near-miss vote on Quebec independence and its impact on Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Komagata Maru', 'komagata-maru', 'A 1914 incident in Vancouver where the Canadian government refused entry to 376 South Asian migrants aboard the ship Komagata Maru, most of whom were Canadian subjects.', 'In May 1914, the Japanese steamship Komagata Maru arrived in Vancouver harbour carrying 376 passengers from British India — most were Sikhs, and all were British subjects. However, Canada had passed regulations specifically designed to prevent South Asian immigration, including the ''continuous journey'' rule requiring immigrants to travel without stopping, which was impossible from India.

For two months, passengers were not allowed to disembark. Most were refused entry and the ship was forced to return to India. On arrival in Calcutta, British colonial authorities fired on the passengers, killing about 20. The Canadian government formally apologized in 2016 when Prime Minister Justin Trudeau addressed the House of Commons and expressed the government''s deep regret for turning away these British subjects based on race. The Komagata Maru incident is a defining example of Canada''s historical discriminatory immigration policies.', 'Imagine being a British subject — technically a citizen of the same empire as Canada — and being refused entry to Canada purely because of your race. That''s what happened in 1914 when 376 Indian Sikhs were turned away from Vancouver. Canada had deliberately designed immigration rules to keep out South Asians. It took over 100 years for the Canadian government to formally apologize.', '[{"title":"Chinese Canadian History","slug":"chinese-canadian-history"},{"title":"Multiculturalism","slug":"multiculturalism"},{"title":"Equality Rights","slug":"equality-rights"}]', 'Why was the Komagata Maru incident of 1914 considered a discriminatory act by the Canadian government?', '["The ship had violated Canadian maritime laws","The Canadian government refused entry to 376 British subjects from India based on race, using discriminatory immigration rules","The passengers were carrying banned goods","The ship did not have proper documentation"]', 1, 'Komagata Maru — Canadian Citizenship Glossary | PassPilot', 'What was the Komagata Maru incident? Learn about the 1914 refusal of South Asian immigrants and Canada''s 2016 apology.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Elections Canada', 'elections-canada', 'The independent, non-partisan federal agency responsible for conducting federal elections and referendums and enforcing Canada''s elections laws.', 'Elections Canada is headed by the Chief Electoral Officer, who is an independent officer of Parliament appointed by resolution of the House of Commons. The agency is responsible for administering federal elections, by-elections, and referendums; maintaining the National Register of Electors; enforcing the Canada Elections Act; and providing public information about elections.

Elections Canada operates independently of the government of the day to ensure the integrity and impartiality of the electoral process. It oversees the work of returning officers in each electoral district, manages polling stations, processes mail-in ballots, and reports election results. The agency also administers the political financing rules that regulate campaign spending, political donations, and party registration.', 'Elections Canada is like the referee for Canadian elections — totally independent of any political party, making sure votes are counted fairly. They set up polling stations, verify who can vote, enforce spending limits for campaigns, and announce results. Because they answer to Parliament (not the PM), no one can pressure them to favour any party.', '[{"title":"Federal Election","slug":"federal-election"},{"title":"Right to Vote","slug":"right-to-vote"},{"title":"Electoral District","slug":"electoral-district"}]', 'What best describes Elections Canada''s relationship to the federal government?', '["It is a cabinet department under the Minister of Democratic Institutions","It is an independent non-partisan agency that reports to Parliament, not the government","It is a provincial agency that coordinates with the federal government","It is a private organization contracted by the government during elections"]', 1, 'Elections Canada — Canadian Citizenship Glossary | PassPilot', 'What is Elections Canada? Learn about the independent agency that conducts federal elections and enforces election laws.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Bank of Canada', 'bank-of-canada', 'Canada''s central bank, responsible for monetary policy, issuing currency, and promoting the economic and financial welfare of Canada.', 'The Bank of Canada was established in 1934 and began operations in 1935. It is a Crown corporation that serves as Canada''s central bank. Its primary mandate is to promote the economic and financial welfare of Canada. It does this through monetary policy (setting the key interest rate to control inflation), issuing Canadian bank notes (paper currency), serving as the government''s fiscal agent, and promoting financial system stability.

The Bank of Canada''s inflation target is to keep the Consumer Price Index (CPI) at 2% — the midpoint of a 1% to 3% range. The Governor of the Bank of Canada is appointed by the federal Cabinet. Unlike the US Federal Reserve, the Bank of Canada operates with a clear mandate and inflation target, which it has followed since 1991. Decisions made by the Bank of Canada affect mortgage rates, business borrowing, and the Canadian dollar''s value.', 'The Bank of Canada is Canada''s financial control centre. It doesn''t serve individual customers like a regular bank — instead, it controls how much money flows through the economy by setting interest rates. Raise rates and borrowing gets more expensive, slowing inflation. Lower rates and borrowing gets cheaper, stimulating growth. Every time the Bank moves its rate, Canadians feel it in their mortgages.', '[{"title":"Canada Revenue Agency","slug":"canada-revenue-agency"},{"title":"Federal Government","slug":"federal-government"},{"title":"GST HST","slug":"gst-hst"}]', 'What is the primary mandate of the Bank of Canada?', '["To provide loans to Canadian businesses and individuals","To promote the economic and financial welfare of Canada, primarily through monetary policy and inflation control","To collect taxes on behalf of the federal government","To manage Canada''s international trade agreements"]', 1, 'Bank of Canada — Canadian Citizenship Glossary | PassPilot', 'What is the Bank of Canada? Learn about Canada''s central bank, monetary policy, and its role in the Canadian economy.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('GST and HST', 'gst-hst', 'The Goods and Services Tax (GST) is a federal consumption tax of 5%; in some provinces it is combined with provincial sales tax into the Harmonized Sales Tax (HST).', 'The Goods and Services Tax (GST) is a 5% federal tax on most goods and services sold in Canada, introduced in 1991 under Prime Minister Brian Mulroney. It replaced the hidden Manufacturers'' Sales Tax. In five provinces — Ontario, Nova Scotia, New Brunswick, Newfoundland and Labrador, and Prince Edward Island — the GST is combined with provincial sales tax into the Harmonized Sales Tax (HST), ranging from 13% to 15%.

Most goods and services are taxable, but certain items are exempt (zero-rated), including basic groceries, prescription drugs, and medical devices. Low-income Canadians can claim a GST/HST credit — a quarterly payment from the CRA to help offset the tax. The GST is one of Canada''s most significant revenue sources, generating tens of billions of dollars annually for federal programs.', 'GST is the tax you see at the bottom of receipts — the government''s cut on most things you buy. In most provinces, it''s combined with provincial sales tax into the HST. Basic groceries aren''t taxed (because food is essential), but most things you buy at a store will have GST/HST added. If your income is low enough, the government sends you a quarterly rebate to help cover it.', '[{"title":"Canada Revenue Agency","slug":"canada-revenue-agency"},{"title":"Tax Return","slug":"tax-return"},{"title":"Federal Government","slug":"federal-government"}]', 'What is the current rate of Canada''s federal Goods and Services Tax (GST)?', '["3%","5%","7%","10%"]', 1, 'GST and HST — Canadian Citizenship Glossary | PassPilot', 'What is GST and HST in Canada? Learn about federal and provincial sales taxes and how they affect Canadians.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Equalization Payments', 'equalization-payments', 'Federal transfer payments made to less prosperous provinces to ensure they can provide comparable public services at comparable tax rates.', 'Equalization is a federal program — enshrined in Section 36 of the Constitution Act, 1982 — that transfers money to provinces whose fiscal capacity (ability to raise revenue) falls below a national average. The goal is to ensure that all Canadians, regardless of which province they live in, can access roughly comparable levels of public services (such as health care and education) without having their provincial government impose undue tax burdens.

The formula for calculating equalization is complex, based on each province''s ability to generate revenue from five standard tax bases. Provinces like Ontario, Alberta, and British Columbia typically do not receive equalization. Provinces like Quebec, Manitoba, and the Atlantic provinces typically do receive equalization payments. The program does not come from any specific province''s taxes — it comes from the federal government''s general revenue, meaning all Canadians contribute through their federal taxes.', 'Equalization is Canada''s way of making sure where you live doesn''t determine what services you receive. If you live in a rich province (like Alberta), your province can fund great hospitals and schools easily. If you live in a poorer province, equalization payments from the federal government help top up the budget so Canadians everywhere get comparable services. It''s one of the ways Canada balances being a federation with being fair.', '[{"title":"Federal Government","slug":"federal-government"},{"title":"Provincial Government","slug":"provincial-government"},{"title":"Medicare","slug":"medicare"}]', 'What is the purpose of Canada''s equalization payment program?', '["To reward provinces with strong economic growth","To help less prosperous provinces provide comparable public services at comparable tax rates","To fund federal infrastructure projects in remote areas","To compensate provinces for hosting federal government offices"]', 1, 'Equalization Payments — Canadian Citizenship Glossary | PassPilot', 'What are Canada''s equalization payments? Learn how this federal program ensures comparable services across all provinces.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Legal Rights (Charter)', 'legal-rights-charter', 'Sections 7–14 of the Charter of Rights and Freedoms, guaranteeing rights in criminal proceedings such as the right to life, liberty, and security, and the right to a fair trial.', 'Sections 7 to 14 of the Canadian Charter of Rights and Freedoms collectively comprise ''Legal Rights,'' which protect individuals in dealings with the justice system. Section 7 guarantees the right to life, liberty, and security of the person. Section 8 protects against unreasonable search and seizure. Section 9 protects against arbitrary detention. Section 10 guarantees the right to be told why you are arrested and the right to retain a lawyer (including the right to be informed of legal aid). Section 11 covers rights of persons charged with an offence, including the right to be tried within a reasonable time and to be presumed innocent. Sections 12–14 protect against cruel treatment, right to an interpreter, and protection against self-incrimination.

These rights apply to all people in Canada — not just citizens — and are most often invoked in criminal proceedings. Evidence obtained in violation of Charter rights may be excluded from trial under Section 24(2). Legal Rights are a cornerstone of Canada''s justice system.', 'Legal Rights in the Charter are your protection when you deal with the police and courts. Think of them as rules the government must follow when it accuses you of something: they must tell you why you''re arrested, you can call a lawyer right away, they can''t search you without good reason, and you''re innocent until proven guilty. These rights exist for everyone in Canada, not just citizens.', '[{"title":"Charter of Rights and Freedoms","slug":"charter-of-rights-and-freedoms"},{"title":"Presumption of Innocence","slug":"presumption-of-innocence"},{"title":"Habeas Corpus","slug":"habeas-corpus"}]', 'Under Section 10(b) of the Canadian Charter, what right does a person have upon arrest or detention?', '["The right to post bail immediately","The right to retain and instruct a lawyer without delay","The right to a jury trial","The right to remain silent permanently"]', 1, 'Legal Rights (Charter) — Canadian Citizenship Glossary | PassPilot', 'What are Legal Rights under the Canadian Charter? Learn about Sections 7–14 and your rights in criminal proceedings.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Meech Lake Accord', 'meech-lake-accord', 'A 1987 package of constitutional amendments intended to bring Quebec into the Constitution Act, 1982, which failed after Manitoba and Newfoundland did not ratify it by the 1990 deadline.', 'The Meech Lake Accord was negotiated in 1987 by Prime Minister Brian Mulroney and all ten provincial premiers to address Quebec''s conditions for signing the Constitution Act, 1982 (which Quebec had refused to sign). The key provisions included recognizing Quebec as a ''distinct society'' within Canada, giving provinces more power over immigration, limiting the federal spending power in areas of provincial jurisdiction, and giving provinces the right to opt out of constitutional amendments.

The Accord required ratification by all ten provincial legislatures within three years. However, it failed in June 1990 when the Manitoba legislature was unable to pass it (Elijah Harper, a Cree MLA, withheld unanimous consent required for fast-tracking) and Newfoundland Premier Clyde Wells called off a ratification vote. The failure of the Meech Lake Accord boosted Quebec nationalism and Bloc Québécois support, contributing to the 1995 Quebec referendum.', 'Meech Lake was Canada''s attempt to finally get Quebec to sign the Constitution. The deal would have recognized Quebec as a ''distinct society.'' But it needed ALL provinces to say yes, and it failed when a Manitoba Indigenous MLA, Elijah Harper, refused to let it pass quickly — partly to protest the lack of Indigenous consultation. Its failure made Quebec''s independence movement stronger.', '[{"title":"Patriation of the Constitution","slug":"patriation-of-the-constitution"},{"title":"Quebec Referendum 1995","slug":"quebec-referendum-1995"},{"title":"Charlottetown Accord","slug":"charlottetown-accord"}]', 'Why did the Meech Lake Accord fail in 1990?', '["The Supreme Court ruled it unconstitutional","Quebec''s legislature voted against it","Manitoba and Newfoundland failed to ratify it by the deadline, partly due to Elijah Harper''s opposition","The federal government withdrew it following public protests"]', 2, 'Meech Lake Accord — Canadian Citizenship Glossary | PassPilot', 'What was the Meech Lake Accord? Learn about the 1987 constitutional package, why it failed, and its impact on Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Charlottetown Accord', 'charlottetown-accord', 'A 1992 package of constitutional reforms that was defeated in a national referendum, addressing Quebec, Indigenous self-government, and Senate reform.', 'After the failure of the Meech Lake Accord, the federal and provincial governments tried again with a broader set of constitutional proposals called the Charlottetown Accord (1992). It addressed multiple issues: recognizing Quebec''s distinct society, guaranteed 25% of Commons seats for Quebec, an elected ''Triple-E'' Senate (equal, elected, effective), and recognition of an inherent right to Indigenous self-government.

Unlike Meech Lake, the Charlottetown Accord was put to a national referendum on October 26, 1992. It was defeated, with about 54% voting ''No.'' The ''No'' vote came from a coalition of those who thought it gave Quebec too much, those who thought it gave too little, and those who opposed Senate reform. The defeat of the Charlottetown Accord effectively ended the era of mega-constitutional negotiations in Canada for many years.', 'After Meech Lake failed, Canada tried again with the Charlottetown Accord — an even bigger deal covering Senate reform, Quebec, and Indigenous rights. This time, they asked all Canadians to vote on it. The result? 54% said no. It was rejected by different groups for completely different reasons — some thought it gave Quebec too much, others too little. It was Canada''s last attempt at major constitutional reform.', '[{"title":"Meech Lake Accord","slug":"meech-lake-accord"},{"title":"Senate Reform","slug":"senate-reform"},{"title":"Indigenous Peoples","slug":"indigenous-peoples"}]', 'How was the Charlottetown Accord decided, and what was the outcome?', '["It was ratified by all provincial legislatures and became law","It was rejected in a national referendum in 1992 with approximately 54% voting No","It passed in most provinces but failed in Quebec only","It was withdrawn by the federal government before a vote could be held"]', 1, 'Charlottetown Accord — Canadian Citizenship Glossary | PassPilot', 'What was the Charlottetown Accord? Learn about the 1992 constitutional package that was defeated in a national referendum.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Fathers of Confederation', 'fathers-of-confederation', 'The 36 political leaders who attended the Confederation conferences (Charlottetown 1864, Quebec 1864, London 1866) and brought about the creation of Canada in 1867.', 'The Fathers of Confederation were the delegates from the British North American colonies who negotiated the terms of Confederation at three conferences: Charlottetown, PEI (September 1864), Quebec City (October 1864), and London, England (1866–67). There were 36 delegates in total. Key figures included John A. Macdonald (Canada West/Ontario), George-Étienne Cartier (Canada East/Quebec), Samuel Leonard Tilley (New Brunswick), Charles Tupper (Nova Scotia), and Leonard Tilley.

The conferences resulted in the 72 Quebec Resolutions, which became the framework for the British North America Act (1867). The three original provinces were Canada (divided into Ontario and Quebec), Nova Scotia, and New Brunswick. Macdonald became the first Prime Minister. Their portraits appear on Canadian currency and their names are commemorated across the country.', 'Think of the Fathers of Confederation as the founding team of Canada — the politicians who sat down in 1864 and designed how Canada would work. There were 36 of them, and they had to convince their colonies that joining together made more sense than staying separate. They created the blueprint (the Quebec Resolutions) that became Canada''s founding law in 1867.', '[{"title":"Confederation","slug":"confederation"},{"title":"John A. Macdonald","slug":"john-a-macdonald"},{"title":"British North America Act","slug":"british-north-america-act"}]', 'How many delegates attended the Confederation conferences that created Canada?', '["10","24","36","50"]', 2, 'Fathers of Confederation — Canadian Citizenship Glossary | PassPilot', 'Who were the Fathers of Confederation? Learn about the 36 political leaders who created Canada in 1867.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Pierre Elliott Trudeau', 'pierre-elliott-trudeau', 'Canada''s 15th Prime Minister (1968–79, 1980–84), who patriated the Constitution, introduced the Charter of Rights, and championed multiculturalism and bilingualism.', 'Pierre Elliott Trudeau was one of the most consequential Prime Ministers in Canadian history. Known for ''Trudeaumania'' when he first took office in 1968, he served two terms (1968–1979 and 1980–1984). His major achievements include implementing the Official Languages Act (1969), making Canada officially bilingual; the War Measures Act during the October Crisis (1970); introducing multiculturalism as federal policy (1971); and most significantly, patriating Canada''s Constitution in 1982 and entrenching the Canadian Charter of Rights and Freedoms.

Trudeau''s constitutional vision met significant resistance from Quebec (which has never signed the 1982 Constitution) and from Indigenous leaders who felt their rights weren''t adequately protected. His government''s imposition of the National Energy Program (NEP) in 1980 created lasting resentment in Alberta. Despite controversies, Trudeau is consistently ranked among Canada''s greatest Prime Ministers for transforming Canada''s national identity through bilingualism, multiculturalism, and the Charter.', 'Pierre Trudeau fundamentally changed what it means to be Canadian. Before him, Canada didn''t have a clear national identity distinct from Britain. He gave Canada the Charter of Rights (protecting everyone''s freedoms), made French and English truly equal as official languages, and proclaimed multiculturalism as Canada''s identity. His father-son legacy continues with Justin Trudeau.', '[{"title":"Charter of Rights and Freedoms","slug":"charter-of-rights-and-freedoms"},{"title":"Patriation of the Constitution","slug":"patriation-of-the-constitution"},{"title":"Official Languages","slug":"official-languages"}]', 'What major constitutional achievement is Prime Minister Pierre Trudeau most associated with?', '["Signing the Kyoto Protocol on climate change","Patriating the Constitution and entrenching the Canadian Charter of Rights and Freedoms in 1982","Negotiating the Free Trade Agreement with the United States","Creating the Canada Pension Plan"]', 1, 'Pierre Elliott Trudeau — Canadian Citizenship Glossary | PassPilot', 'Who was Pierre Trudeau? Learn about Canada''s 15th PM, the Charter of Rights, and his lasting impact on Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Nellie McClung', 'nellie-mcclung', 'A leading Canadian suffragist, author, and politician who fought for women''s voting rights and was one of the Famous Five in the Persons Case.', 'Nellie McClung (1873–1951) was one of Canada''s most influential social reformers. Born in Ontario and raised in Manitoba, she became a teacher and then a celebrated novelist. She was a passionate advocate for women''s suffrage, temperance, and social reform. In 1916, she helped win women the right to vote in Manitoba — the first province to grant women provincial voting rights. She later served as a Member of the Alberta Legislative Assembly (1921–1926).

McClung was one of the Famous Five who petitioned the Supreme Court in the Persons Case, winning the landmark 1929 ruling that women are legally persons. She represented Canada at the League of Nations in Geneva in 1938. Her famous quote, ''Never retract, never explain, never apologize — get things done and let them howl,'' captures her determined spirit. McClung is one of only six women on Canada''s Walk of Fame in Ottawa.', 'Nellie McClung was one of the most fearless voices for women''s rights in Canadian history. She didn''t just talk about equality — she organized, wrote books, gave speeches, and ran for office. She helped get women the vote in Manitoba in 1916 and won the Persons Case in 1929. She''s a reminder that the rights Canadians take for granted today were hard-won by real people.', '[{"title":"Famous Five","slug":"famous-five"},{"title":"Persons Case","slug":"persons-case"},{"title":"Right to Vote","slug":"right-to-vote"}]', 'What was Nellie McClung''s role in achieving women''s voting rights in Canada?', '["She was the first female Prime Minister of Canada","She led the campaign that won women provincial voting rights in Manitoba (1916) and was one of the Famous Five in the Persons Case","She drafted the section on equality rights in the Charter of Rights and Freedoms","She founded the New Democratic Party to advance women''s rights"]', 1, 'Nellie McClung — Canadian Citizenship Glossary | PassPilot', 'Who was Nellie McClung? Learn about the Canadian suffragist who fought for women''s voting rights and the Persons Case.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Terry Fox', 'terry-fox', 'A Canadian athlete and cancer activist who, after losing his leg to cancer, ran his ''Marathon of Hope'' across Canada in 1980 to raise money for cancer research.', 'Terry Fox (1958–1981) was a 21-year-old from Port Coquitlam, British Columbia, when he began his Marathon of Hope on April 12, 1980. Having lost his right leg to osteosarcoma (bone cancer) at 18, Fox ran across Canada on a prosthetic leg, averaging 42 km (26 miles) a day. His goal was to run the full width of Canada — roughly 8,000 km — to raise $1 for every Canadian for cancer research.

Fox ran for 143 days, covering 5,373 km (3,339 miles) through Newfoundland, Nova Scotia, New Brunswick, Quebec, Ontario, and into Thunder Bay, Ontario, when he was forced to stop on September 1, 1980, after cancer spread to his lungs. He died on June 28, 1981. The Terry Fox Foundation continues his legacy, having raised over $850 million for cancer research. Annual Terry Fox Runs are held in September in communities across Canada and around the world.', 'Terry Fox is one of Canada''s greatest heroes — not for anything political, but for sheer courage and selflessness. He had already lost his leg to cancer, but instead of giving up, he decided to run across an entire continent to help other cancer patients. He didn''t finish, but his legacy has raised over $850 million for cancer research. He shows what individual determination can achieve.', '[{"title":"Order of Canada","slug":"order-of-canada"},{"title":"Canadian Values","slug":"canadian-citizen"},{"title":"Provinces of Canada","slug":"provinces-of-canada"}]', 'What was the goal of Terry Fox''s Marathon of Hope in 1980?', '["To set a world record for long-distance running on a prosthetic leg","To run across Canada to raise money for cancer research — $1 per Canadian","To raise awareness about accessibility rights for people with disabilities","To protest the lack of government funding for medical research"]', 1, 'Terry Fox — Canadian Citizenship Glossary | PassPilot', 'Who was Terry Fox? Learn about his Marathon of Hope, his legacy, and why he is one of Canada''s greatest heroes.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Wayne Gretzky', 'wayne-gretzky', 'Canadian ice hockey player known as ''The Great One'' — widely considered the greatest hockey player of all time, holding 61 NHL records.', 'Wayne Gretzky (born 1961, Brantford, Ontario) played professional hockey from 1979 to 1999, primarily with the Edmonton Oilers, Los Angeles Kings, St. Louis Blues, and New York Rangers. He holds or shares 61 NHL records, including the most goals (894), most assists (1,963), and most total points (2,857) — a record so dominant that his assist total alone exceeds any other player''s total points.

Gretzky led the Edmonton Oilers to four Stanley Cup championships (1984, 1985, 1987, 1988) and is credited with helping popularize hockey in the United States during his years with the LA Kings. He is one of only two players to have his jersey number (#99) retired across the entire NHL. Gretzky was inducted into the Hockey Hall of Fame in 1999, the same year he retired. He holds the Companion of the Order of Canada.', 'Wayne Gretzky is to hockey what Mozart is to music — so far above everyone else that comparisons seem unfair. His record points (2,857) is unimaginable — the next closest player has about 1,900. He''s called ''The Great One'' for good reason. He made hockey exciting for fans who had never watched it, especially in the US. In Canada, he''s a national treasure.', '[{"title":"Hockey","slug":"hockey"},{"title":"Order of Canada","slug":"order-of-canada"},{"title":"Canadian Culture","slug":"multiculturalism"}]', 'What nickname is hockey legend Wayne Gretzky known by?', '["The Ice King","The Golden Jet","The Great One","The Rocket"]', 2, 'Wayne Gretzky — Canadian Citizenship Glossary | PassPilot', 'Who is Wayne Gretzky? Learn about ''The Great One'' and why he is considered the greatest hockey player of all time.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Tommy Douglas', 'tommy-douglas', 'Premier of Saskatchewan (1944–61) and founder of the NDP, best known for introducing publicly funded Medicare to Canada — voted ''Greatest Canadian'' in 2004.', 'Thomas Clement (Tommy) Douglas (1904–1986) was a Baptist minister turned politician who became one of Canada''s most important social reformers. As Premier of Saskatchewan for 17 years, he led the first socialist government in North America. In 1962, his government introduced Medicare — publicly funded universal health insurance — despite fierce opposition from doctors who went on strike. The success of Saskatchewan''s Medicare became the model for Canada-wide Medicare under the Canada Health Act (1984).

Douglas also served as the first federal leader of the New Democratic Party (NDP) from 1961 to 1971. He was inducted into the Order of Canada in 1981. In 2004, CBC viewers voted Tommy Douglas the ''Greatest Canadian'' in a national poll, recognizing his transformation of Canadian social policy.', 'Tommy Douglas gave Canada Medicare — the idea that every Canadian should get health care without having to worry about the bill. He did it first in Saskatchewan, facing massive opposition from doctors who went on strike. But when it worked, the rest of Canada adopted it. The 2004 poll that voted him ''Greatest Canadian'' shows how deeply Canadians value their public health care.', '[{"title":"Medicare","slug":"medicare"},{"title":"Canada Health Act","slug":"canada-health-act"},{"title":"Order of Canada","slug":"order-of-canada"}]', 'What major social policy is Tommy Douglas most credited with introducing to Canada?', '["The Canada Pension Plan","Publicly funded universal Medicare (health insurance)","The Charter of Rights and Freedoms","Employment Insurance"]', 1, 'Tommy Douglas — Canadian Citizenship Glossary | PassPilot', 'Who was Tommy Douglas? Learn about the ''Greatest Canadian'' who introduced Medicare and changed Canadian social policy.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('John Diefenbaker', 'john-diefenbaker', 'Canada''s 13th Prime Minister (1957–63), known for the Canadian Bill of Rights (1960) and for being the first PM to appoint a woman to Cabinet.', 'John George Diefenbaker (1895–1979) was a Saskatchewan lawyer and Conservative politician who led Canada''s government from 1957 to 1963. In the 1958 election, his Progressive Conservative party won the largest majority government in Canadian history up to that time (208 of 265 seats). Diefenbaker was a passionate defender of civil liberties. His most lasting legislative achievement was the Canadian Bill of Rights (1960), a federal statute protecting individual rights and freedoms — a precursor to the Charter of Rights and Freedoms (1982).

Diefenbaker appointed Ellen Fairclough as Secretary of State in 1957, making her Canada''s first female federal cabinet minister. He also extended the franchise (right to vote) to Indigenous Canadians in 1960. His government is also known for the Avro Arrow controversy — the cancellation of the CF-105, a supersonic jet fighter program, in 1959.', 'Diefenbaker was a fierce defender of individual rights at a time when few politicians talked about such things. He created Canada''s first Bill of Rights in 1960 — before Trudeau''s Charter. He also gave Indigenous Canadians the right to vote (they had been excluded until 1960!) and appointed the first female Cabinet minister. His legacy is often overshadowed but was genuinely important.', '[{"title":"Canadian Bill of Rights","slug":"canadian-bill-of-rights"},{"title":"Right to Vote","slug":"right-to-vote"},{"title":"Charter of Rights and Freedoms","slug":"charter-of-rights-and-freedoms"}]', 'What significant rights legislation did Prime Minister Diefenbaker introduce in 1960?', '["The Canadian Charter of Rights and Freedoms","The Canadian Bill of Rights — a federal statute protecting individual rights","The Multiculturalism Act","The Official Languages Act"]', 1, 'John Diefenbaker — Canadian Citizenship Glossary | PassPilot', 'Who was John Diefenbaker? Learn about Canada''s 13th PM, the Canadian Bill of Rights, and Indigenous voting rights.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Atlantic Provinces', 'atlantic-provinces', 'The four eastern provinces of Canada: Nova Scotia, New Brunswick, Prince Edward Island, and Newfoundland and Labrador.', 'The Atlantic provinces (sometimes called ''Atlantic Canada'') are the four easternmost provinces. Nova Scotia, New Brunswick, and Prince Edward Island are also called the ''Maritime provinces'' (or ''the Maritimes''). Newfoundland and Labrador joined Confederation last, in 1949. The region is known for its distinctive culture, seafood (particularly lobster and cod), strong fishing and offshore oil industries, Celtic and Acadian heritage, and close-knit communities.

Historically, the Atlantic provinces were the birthplace of Canadian Confederation — the Charlottetown Conference (1864) that started the Confederation process was held in Charlottetown, PEI. The region has faced economic challenges compared to central and western Canada, relying on equalization payments, Employment Insurance, and federal transfers. Cities include Halifax (NS), Moncton and Fredericton (NB), Charlottetown (PEI), and St. John''s (NL).', 'The Atlantic provinces are Canada''s eastern ocean-facing provinces — known for fishing, lobster, lighthouses, and strong community ties. They were where Confederation was born (at the Charlottetown Conference in PEI), yet Newfoundland only joined Canada in 1949. These provinces rely more on federal support than wealthier central or western provinces, which is why equalization payments matter so much there.', '[{"title":"Confederation","slug":"confederation"},{"title":"Atlantic Canada","slug":"atlantic-canada"},{"title":"Equalization Payments","slug":"equalization-payments"}]', 'Which province was the last to join Confederation, doing so in 1949?', '["Prince Edward Island","Nova Scotia","New Brunswick","Newfoundland and Labrador"]', 3, 'Atlantic Provinces — Canadian Citizenship Glossary | PassPilot', 'What are Canada''s Atlantic Provinces? Learn about Nova Scotia, New Brunswick, PEI, and Newfoundland and Labrador.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Manitoba', 'manitoba', 'Canada''s fifth-largest province, located in the centre of Canada, known as the ''keystone province''; its capital is Winnipeg.', 'Manitoba became Canada''s fifth province on July 15, 1870, through the Manitoba Act — largely due to the political leadership of Louis Riel, who led the Red River Resistance of 1869–70 to ensure Métis rights. Manitoba is often called the ''Keystone Province'' because of its central location. Winnipeg, the capital and largest city, is located at the geographic centre of Canada.

Manitoba has significant French-speaking and Indigenous populations, along with large communities of Ukrainian, Mennonite, and Filipino Canadians. The province''s economy relies on agriculture (wheat, canola), manufacturing, mining, and hydroelectric power. Lake Winnipeg is one of the largest freshwater lakes in the world. The province observes Louis Riel Day on the third Monday of February as a statutory holiday.', 'Manitoba is right in the middle of Canada — physically and culturally. It''s where Louis Riel fought for Métis rights and where the ''Keystone Province'' nickname comes from. Winnipeg is as far from any ocean as you can get in Canada, making it a gateway between eastern and western Canada. Manitoba''s diverse population — Ukrainian, Mennonite, Indigenous, Filipino — reflects Canada''s multicultural character.', '[{"title":"Louis Riel","slug":"louis-riel"},{"title":"Métis","slug":"metis"},{"title":"Prairies","slug":"prairies"}]', 'What event led directly to Manitoba becoming a province in 1870?', '["A federal government decision to expand westward","Louis Riel''s Red River Resistance, which secured Métis rights and led to the Manitoba Act","The completion of the Canadian Pacific Railway through the region","A referendum held by the residents of Rupert''s Land"]', 1, 'Manitoba — Canadian Citizenship Glossary | PassPilot', 'What is Manitoba? Learn about the Keystone Province, Winnipeg, Louis Riel, and Manitoba''s place in Canadian history.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('British Columbia', 'british-columbia', 'Canada''s westernmost province, known for its mountains, Pacific coastline, and as the third most populous province; Victoria is the capital, Vancouver is the largest city.', 'British Columbia (BC) joined Confederation on July 20, 1871, on the condition that Canada build a transcontinental railway to connect it to eastern Canada. The Canadian Pacific Railway''s completion in 1885 fulfilled this promise. BC is Canada''s third-most populous province and the gateway to Asia-Pacific trade. Vancouver is Canada''s third-largest city and one of the most ethnically diverse cities in North America, with large Chinese-Canadian, South Asian, and Indigenous populations.

BC is known for stunning natural beauty — the Rocky Mountains, Coast Mountains, Fraser River, Pacific Ocean coastline, and temperate rainforests. Major industries include technology, film and TV production (''Hollywood North''), forestry, mining, and tourism. Victoria, the capital on Vancouver Island, was the original centre of British and colonial settlement. The province is home to numerous First Nations and has seen significant modern treaty-making with Indigenous peoples.', 'British Columbia is Canada''s Pacific province — mountains, ocean, and rain forests. Vancouver is one of the world''s most livable cities and an economic bridge between Canada and Asia. BC only agreed to join Canada in 1871 if Ottawa built a railway — which is why the CPR was built. Today, BC''s tech industry, film production, and trade make it one of Canada''s economic engines.', '[{"title":"Canadian Pacific Railway","slug":"canadian-pacific-railway"},{"title":"Confederation","slug":"confederation"},{"title":"Multiculturalism","slug":"multiculturalism"}]', 'On what condition did British Columbia agree to join Confederation in 1871?', '["The federal government would fund BC''s healthcare system","Ottawa would build a transcontinental railway connecting BC to eastern Canada","BC would be allowed to set its own immigration policies","The federal government would forgive BC''s colonial-era debts"]', 1, 'British Columbia — Canadian Citizenship Glossary | PassPilot', 'What is British Columbia? Learn about Canada''s westernmost province, Vancouver, and BC''s role in Confederation.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Alberta', 'alberta', 'A western Canadian province known for oil sands, agriculture, and the Rocky Mountains; Edmonton is the capital, Calgary is the largest city.', 'Alberta became a province on September 1, 1905, along with Saskatchewan. It is located between BC and Saskatchewan, bordered by Montana to the south. Alberta is Canada''s fourth-most populous province and is known for its oil sands — one of the world''s largest oil reserves, centred around Fort McMurray. Oil and natural gas production have made Alberta historically one of Canada''s wealthiest provinces, which does not receive equalization payments.

The province is also known for agriculture (beef cattle, wheat), the Rocky Mountains along its western border (Banff and Jasper National Parks), and a conservative political culture. Calgary hosts the famous Calgary Stampede rodeo every July. Edmonton, the capital, is a gateway to Canada''s north. Alberta does not have a provincial sales tax. Indigenous peoples including Blackfoot, Cree, and Métis peoples have deep historical roots in the region.', 'Alberta is Canada''s energy powerhouse — massive oil sands make it one of the wealthiest provinces. This wealth means Alberta doesn''t receive equalization payments, and Albertans sometimes feel they subsidize the rest of Canada. The province is also home to spectacular Rocky Mountain scenery (Banff!) and strong Indigenous history. Its identity is distinct from other provinces — more frontier, more independent-minded.', '[{"title":"Prairies","slug":"prairies"},{"title":"Equalization Payments","slug":"equalization-payments"},{"title":"Rocky Mountains","slug":"rocky-mountains"}]', 'In what year did Alberta become a Canadian province?', '["1867","1870","1905","1930"]', 2, 'Alberta — Canadian Citizenship Glossary | PassPilot', 'What is Alberta? Learn about the oil sands province, Calgary, Edmonton, and Alberta''s role in Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Saskatchewan', 'saskatchewan', 'A prairie province that joined Canada in 1905, known as Canada''s breadbasket for its wheat production; Regina is the capital, Saskatoon is the largest city.', 'Saskatchewan became a province on September 1, 1905, along with Alberta. Located between Alberta and Manitoba, the province is known for its flat prairies, vast wheat fields, and big skies. Saskatchewan produces approximately 40% of Canada''s wheat and is one of the world''s largest grain exporters. The province also has significant potash deposits — Saskatchewan has about one-third of the world''s potash reserves, used in fertilizer.

Saskatoon is the province''s largest city; Regina is the capital and home to the Royal Canadian Mounted Police''s training academy (Depot Division). Tommy Douglas, who introduced Medicare to Canada, was Premier of Saskatchewan. The province has a significant Métis and First Nations population with deep historical ties to the Cree, Assiniboine, and other peoples. Winter temperatures can drop to -40°C on the prairies.', 'Saskatchewan is Canada''s wheat capital — nearly half of Canada''s wheat grows here. It''s also where Tommy Douglas invented Medicare, which eventually became national policy. The province is known for flat prairies (you can see the curvature of the Earth!), extreme winters, and strong community spirit. It''s the backbone of Canada''s food supply.', '[{"title":"Prairies","slug":"prairies"},{"title":"Tommy Douglas","slug":"tommy-douglas"},{"title":"Medicare","slug":"medicare"}]', 'What is Saskatchewan most known for producing, earning it the nickname ''Canada''s breadbasket''?', '["Oil and natural gas","Wheat and grain — approximately 40% of Canada''s wheat","Hydroelectric power","Automobiles and steel"]', 1, 'Saskatchewan — Canadian Citizenship Glossary | PassPilot', 'What is Saskatchewan? Learn about Canada''s breadbasket province, wheat production, and Tommy Douglas.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Quebec', 'quebec', 'Canada''s largest province by area, predominantly French-speaking, with Montreal as its largest city and Quebec City as its capital and the only walled city in North America.', 'Quebec is Canada''s second-most populous province and by far the largest by area. It is the heart of French Canada, with over 80% of its population speaking French as a first language. French is the only official language of Quebec under the Quebec Charter of the French Language (Bill 101, 1977). Quebec City is the provincial capital and the only remaining walled city in North America north of Mexico. Montreal, the largest city, is the second-largest French-speaking city in the world after Paris.

Quebec''s cultural heritage includes a distinct Francophone culture, Catholicism, civil law tradition (based on the Napoleonic Code rather than common law), and the Québécois national identity. The province has seen significant independence movements, culminating in the 1980 and 1995 referendums. Major industries include aerospace, pharmaceuticals, information technology, hydroelectric power, and tourism. Quebec contributes significantly to Canadian culture through literature, film, music, and cuisine (poutine!).', 'Quebec is the soul of French Canada. Its language, culture, civil law, and identity are distinctly different from the rest of Canada — and Quebecers are proud of it. Two referendums on independence (1980, 1995) show how seriously many Quebecers take the question of whether Quebec should be its own country. Whether Quebec stays in Canada or pushes for independence remains one of the country''s great ongoing questions.', '[{"title":"Official Languages","slug":"official-languages"},{"title":"Quebec Referendum 1995","slug":"quebec-referendum-1995"},{"title":"Quiet Revolution","slug":"quiet-revolution"}]', 'What is significant about Quebec City that distinguishes it from other cities in North America?', '["It is Canada''s oldest city","It is the only walled city north of Mexico in North America","It has Canada''s largest French-speaking population","It is the only city where both official languages are equally spoken"]', 1, 'Quebec — Canadian Citizenship Glossary | PassPilot', 'What is Quebec? Learn about Canada''s French-speaking province, Quebec City, Montreal, and Quebec''s unique identity.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Ontario', 'ontario', 'Canada''s most populous province, home to Toronto (Canada''s largest city) and Ottawa (the national capital); the economic centre of Canada.', 'Ontario is Canada''s most populous province, home to about 38% of the country''s population. It is bordered by Quebec to the east, Manitoba to the west, Hudson Bay and James Bay to the north, and the Great Lakes and US states to the south. Toronto, with a metropolitan population of over 6 million, is Canada''s largest city and financial capital. Ottawa, situated on the Ontario-Quebec border, is Canada''s national capital.

Ontario entered Confederation as one of the four original provinces in 1867 (called Canada West before Confederation). The province has a diversified economy: financial services, automotive manufacturing (Windsor, Oshawa), technology (Toronto''s ''Silicon Valley North''), mining, and agriculture. Niagara Falls, the CN Tower, the Rideau Canal, and Algonquin Provincial Park are major attractions. Ontario has the largest Indigenous population of any province, including Six Nations of the Grand River — the largest First Nations reserve in Canada.', 'Ontario is Canada''s engine room — it has the most people, the biggest economy, and the national capital. If Canada were a company, Ontario would be headquarters. But that dominance sometimes creates resentment from other provinces who feel Ontario has too much political power. Understanding Ontario means understanding the tensions that run through Canadian federalism.', '[{"title":"Confederation","slug":"confederation"},{"title":"Ottawa","slug":"ottawa"},{"title":"Equalization Payments","slug":"equalization-payments"}]', 'Approximately what percentage of Canada''s population lives in Ontario?', '["20%","28%","38%","50%"]', 2, 'Ontario — Canadian Citizenship Glossary | PassPilot', 'What is Ontario? Learn about Canada''s most populous province, Toronto, Ottawa, and Ontario''s role in Confederation.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Dieppe Raid', 'dieppe-raid', 'A disastrous Allied raid on the French coastal town of Dieppe on August 19, 1942, in which approximately 3,600 of 5,000 Canadian soldiers were killed, wounded, or captured.', 'Operation Jubilee — the Dieppe Raid — was an Allied amphibious assault on the German-occupied port of Dieppe, France, on August 19, 1942. Of the approximately 6,000 assault troops, nearly 5,000 were Canadians from the 2nd Canadian Infantry Division. The raid was a military disaster. Within hours, about 3,623 Canadian soldiers were killed, wounded, or captured. Only a small fraction reached and briefly held their objectives before being repulsed.

Despite the catastrophic losses, the lessons learned at Dieppe — about the need for better intelligence, naval fire support, and coordination — influenced the planning for the D-Day invasion of Normandy in June 1944. The Dieppe Raid is remembered as a tragic example of Canadian courage and sacrifice. The failure at Dieppe also demonstrated that Canadian forces were capable of learning and adapting, which they proved at D-Day and in the Liberation of the Netherlands.', 'Dieppe was a tragic military disaster — 3,600 Canadian soldiers were killed, captured, or wounded in a single day in 1942. It was poorly planned and the Germans were ready for them. But the harsh lessons learned helped make D-Day successful two years later. Canadians remember Dieppe as a sacrifice that, while devastating, was not entirely in vain.', '[{"title":"World War II","slug":"world-war-ii"},{"title":"Vimy Ridge","slug":"vimy-ridge"},{"title":"Remembrance Day","slug":"remembrance-day"}]', 'What is the historical significance of the 1942 Dieppe Raid for Canada?', '["It was Canada''s greatest military victory of WWII","It was a costly military disaster in which approximately 3,600 of 5,000 Canadian soldiers were killed, wounded, or captured","It led directly to Canada declaring war on Germany","It was Canada''s first military operation in the Pacific"]', 1, 'Dieppe Raid — Canadian Citizenship Glossary | PassPilot', 'What was the Dieppe Raid? Learn about the 1942 WWII disaster and the sacrifice of Canadian soldiers.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('D-Day and Liberation of Normandy', 'd-day-normandy', 'On June 6, 1944, Canadian forces stormed Juno Beach as part of the D-Day invasion of Normandy, France — one of Canada''s most celebrated military achievements.', 'Operation Overlord — the D-Day invasion on June 6, 1944 — was the largest seaborne invasion in history. Canadian forces were assigned to storm Juno Beach, one of five landing sectors. Approximately 14,000 Canadian soldiers landed on Juno Beach that day, suffering about 1,074 casualties (359 killed). Canadian forces advanced further inland on D-Day than any other Allied force, capturing Courseulles-sur-Mer and other objectives.

Following D-Day, Canadian forces played a crucial role in the liberation of northwestern Europe. Canada liberated the Scheldt Estuary (1944), which opened the port of Antwerp and allowed Allied supply lines to function. Most significantly, Canada liberated much of the Netherlands from German occupation in 1944–45. The Dutch people have maintained a deep gratitude to Canada ever since — every year the Netherlands sends 20,000 tulips to Ottawa as a symbol of thanks.', 'On D-Day, Canada had its own beach (Juno) and its soldiers advanced further inland than any other Allied force that day. After D-Day, Canadian troops liberated the Netherlands — which is why the Dutch still send thousands of tulips to Ottawa every year as a thank-you. Canada punched way above its weight in WWII, and D-Day was the highlight.', '[{"title":"World War II","slug":"world-war-ii"},{"title":"Dieppe Raid","slug":"dieppe-raid"},{"title":"Remembrance Day","slug":"remembrance-day"}]', 'What was Canada''s assigned landing sector during the D-Day invasion of Normandy on June 6, 1944?', '["Omaha Beach","Gold Beach","Juno Beach","Utah Beach"]', 2, 'D-Day and Liberation of Normandy — Canadian Citizenship Glossary | PassPilot', 'What was Canada''s role on D-Day? Learn about Juno Beach, the Normandy invasion, and the liberation of the Netherlands.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Parliament Buildings', 'parliament-buildings', 'The complex of Gothic Revival buildings on Parliament Hill in Ottawa where the Parliament of Canada meets, including the Centre Block, East Block, and West Block.', 'The Parliament Buildings sit on Parliament Hill, a limestone escarpment overlooking the Ottawa River. The main building is the Centre Block, which contains the House of Commons chamber, the Senate chamber, and the Peace Tower — a 92-metre clock tower with the Carillon bells and the Memorial Chamber honouring fallen Canadians. The original Centre Block was destroyed by fire in 1916 (only the Library of Parliament survived) and was rebuilt and completed in 1922.

The Centre Block underwent a major renovation starting in 2018. During this time, Parliament used the West Block and Senate of Canada Building. East Block houses offices and committee rooms and is preserved as a heritage site. The Library of Parliament, built in 1876 in a circular Gothic-revival style, survived the 1916 fire and is one of Ottawa''s most beautiful buildings. Parliament Hill also hosts ceremonies, citizenship events, and Canada Day celebrations.', 'The Parliament Buildings are Canada''s democratic heart — where laws are debated and passed. The Centre Block burned down in 1916 during WWI and was rebuilt with the Peace Tower as a memorial. The Library of Parliament survived the fire because its metal fire doors were closed in time. Today, Parliament Hill is where new citizens take their oath at citizenship ceremonies and where Canadians celebrate Canada Day.', '[{"title":"Parliament","slug":"parliament"},{"title":"Ottawa","slug":"ottawa"},{"title":"Peace Tower","slug":"peace-tower"}]', 'What happened to the original Centre Block of the Parliament Buildings in 1916?', '["It was demolished and replaced with a modern design","It was destroyed by fire, with only the Library of Parliament surviving","It was converted into a museum","It was relocated to another site in Ottawa"]', 1, 'Parliament Buildings — Canadian Citizenship Glossary | PassPilot', 'What are the Parliament Buildings? Learn about Canada''s Parliament Hill, the Centre Block, and the Peace Tower.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Governor General Julie Payette', 'governor-general-past', 'A brief overview of recent Governors General, including Julie Payette (2017–21) and Mary Simon (2021–present), Canada''s first Indigenous Governor General.', 'The Governor General is Canada''s representative of the Monarch. Recent Governors General include Julie Payette (2017–2021), a Canadian astronaut who was the first Governor General with a background in science and space exploration. Payette resigned in January 2021 following a workplace review. Mary Simon was appointed in July 2021, becoming Canada''s first Indigenous Governor General — a landmark appointment reflecting reconciliation efforts. Simon, an Inuk from Nunavik, Quebec, is a former diplomat and Arctic rights advocate.

Previous notable Governors General include Adrienne Clarkson (1999–2005), the first person of colour to hold the office; Michaëlle Jean (2005–2010), a Haitian-born Canadian; and David Johnston (2010–2017). The appointment is made by the Monarch on the advice of the Prime Minister for a term typically of 5 years.', 'Canada''s Governor General has increasingly reflected the country''s diversity. Mary Simon in 2021 made history as Canada''s first Indigenous GG — an important step for reconciliation. The office is mostly ceremonial, but symbolic appointments like Simon''s send important messages about whose contributions Canada values.', '[{"title":"Governor General","slug":"governor-general"},{"title":"Indigenous Peoples","slug":"indigenous-peoples"},{"title":"Monarch","slug":"monarch"}]', 'Who was appointed Canada''s first Indigenous Governor General in 2021?', '["Julie Payette","Adrienne Clarkson","Mary Simon","Michaëlle Jean"]', 2, 'Governor General — Recent History — Canadian Citizenship Glossary | PassPilot', 'Who are Canada''s recent Governors General? Learn about Mary Simon, Canada''s first Indigenous GG, and others.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Immigration Levels Plan', 'immigration-levels-plan', 'An annual plan published by IRCC setting Canada''s targets for permanent resident admissions across economic, family, and refugee categories.', 'Canada''s Immigration Levels Plan is a multi-year targets document that IRCC tables in Parliament each November. It sets out how many permanent residents Canada plans to admit in the coming years across three main categories: Economic (skilled workers, entrepreneurs, caregivers — approximately 60%), Family Reunification (spouses, parents, grandparents — approximately 25%), and Refugees and Humanitarian (government-assisted refugees, privately sponsored refugees — approximately 15%).

Canada''s immigration targets have grown significantly. The 2023 targets were set at 465,000 new permanent residents, with plans for similar levels through 2025. Canada''s immigration policy is driven by demographic needs: aging population, low birth rate, labour force shortages, and the need to sustain pension and health care systems. The Levels Plan is a key policy document because it determines not just numbers but also which programs (Express Entry, PNP, etc.) will have the highest number of spots.', 'Each year, Canada publishes a plan saying exactly how many immigrants it wants to admit and in what categories. It''s Canada saying: ''we need THIS many skilled workers, THIS many family members, THIS many refugees.'' Unlike most countries, Canada has a transparent, positive attitude toward immigration — it''s not just tolerated, it''s planned for and seen as essential.', '[{"title":"Express Entry","slug":"express-entry"},{"title":"Provincial Nominee Program","slug":"provincial-nominee-program"},{"title":"IRCC","slug":"ircc"}]', 'What are the three main categories in Canada''s annual Immigration Levels Plan?', '["Skilled, Unskilled, and Student","Economic, Family Reunification, and Refugees/Humanitarian","Provincial, Federal, and International","Workers, Students, and Visitors"]', 1, 'Immigration Levels Plan — Canadian Citizenship Glossary | PassPilot', 'What is Canada''s Immigration Levels Plan? Learn about annual immigration targets across economic, family, and refugee categories.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Canadian Experience Class', 'canadian-experience-class-detail', 'An Express Entry stream for people with at least one year of skilled Canadian work experience who want to become permanent residents.', 'The Canadian Experience Class (CEC) is one of the three federal programs managed under Express Entry. It is designed for people who are already in Canada on a temporary basis (work permit holders, international graduates) and have accumulated at least one year of skilled work experience in Canada within the last three years. The key advantage is that applicants are already adapted to Canadian society, and their Canadian work experience is highly valued.

CEC applicants must meet language requirements (CLB 5 for NOC TEER 0 and 1 jobs, CLB 4 for NOC TEER 2 and 3 jobs). There is no minimum points score requirement independent of Express Entry — all CEC-eligible candidates enter the Express Entry pool and compete in draws. CEC draws can be program-specific (CEC-only draws) or all-program draws. CEC applicants typically have higher CRS scores because Canadian work experience earns significant points in the Comprehensive Ranking System.', 'Canadian Experience Class is basically Canada saying: ''If you''ve already been working here for a year and are integrated into our society — you''re probably a good fit for permanent residence.'' It rewards people who are already contributing to Canada. International students who graduate and work here are prime candidates — Canada wants to keep the talented people it has already trained.', '[{"title":"Express Entry","slug":"express-entry"},{"title":"Comprehensive Ranking System","slug":"comprehensive-ranking-system"},{"title":"Invitation to Apply","slug":"invitation-to-apply"}]', 'What is the minimum Canadian work experience required to apply through the Canadian Experience Class?', '["6 months of skilled work","1 year of skilled work in Canada within the last 3 years","2 years of any work in Canada","3 years of continuous work in Canada"]', 1, 'Canadian Experience Class — Canadian Citizenship Glossary | PassPilot', 'What is the Canadian Experience Class? Learn about this Express Entry stream for people with Canadian work experience.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Temporary Foreign Worker Program', 'temporary-foreign-worker-program', 'A federal program allowing Canadian employers to hire foreign workers on a temporary basis when Canadians are not available to fill the positions.', 'The Temporary Foreign Worker Program (TFWP) allows Canadian employers to hire foreign nationals for temporary work when qualified Canadians or permanent residents are not available. Employers must typically obtain a Labour Market Impact Assessment (LMIA) from Employment and Social Development Canada (ESDC), demonstrating that hiring a foreign worker will not negatively affect Canadian workers. The LMIA process requires advertising the position in Canada first.

There are multiple streams within the TFWP, including the High-Wage Stream, Low-Wage Stream, Agricultural Stream, and Live-in Caregiver Program. Working under the TFWP gives workers employer-specific work permits (closed permits) — they cannot change employers without applying for a new permit. The TFWP is distinct from the International Mobility Program (IMP), which includes CUSMA workers, intra-company transfers, and reciprocal exchange programs that don''t require an LMIA.', 'The TFWP lets Canadian employers hire from abroad when they can''t find Canadians for the job. Employers must prove they tried to hire locally first (through an LMIA assessment). Workers get a permit tied to a specific employer — they can''t just switch jobs. It''s different from an open work permit. For many workers, the TFWP is a stepping stone toward permanent residency.', '[{"title":"Work Permit","slug":"work-permit"},{"title":"Labour Market Impact Assessment","slug":"lmia"},{"title":"Open Work Permit","slug":"open-work-permit"}]', 'What must a Canadian employer generally obtain before hiring a worker through the Temporary Foreign Worker Program?', '["A Federal Work Authorization","A Labour Market Impact Assessment (LMIA) from ESDC","A nomination from a provincial government","A clearance from the RCMP"]', 1, 'Temporary Foreign Worker Program — Canadian Citizenship Glossary | PassPilot', 'What is Canada''s Temporary Foreign Worker Program? Learn about LMIA, employer requirements, and work permits.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('LMIA', 'lmia', 'Labour Market Impact Assessment — a document from ESDC confirming that hiring a foreign worker will not harm Canadian workers, required by many employers in the TFWP.', 'A Labour Market Impact Assessment (LMIA) is a document that an employer in Canada may need to get before hiring a foreign worker. The LMIA process is administered by Employment and Social Development Canada (ESDC). To obtain a positive LMIA, the employer must advertise the position in Canada for a specified period, demonstrate that no qualified Canadian or permanent resident could fill the role, and show that hiring a foreign worker will have a neutral or positive impact on the Canadian labour market.

A positive LMIA can then be used by a foreign worker as part of their work permit application. LMIAs are required for most Temporary Foreign Worker Program streams. However, many work permit categories are LMIA-exempt — these include International Mobility Program workers, CUSMA/USMCA professionals, intra-company transferees, and significant benefit exemptions for entrepreneurs and researchers.', 'An LMIA is proof that an employer genuinely couldn''t find a Canadian for the job. The company has to advertise the position, show the government they tried, and only THEN can they bring in someone from abroad. It''s Canada''s way of protecting Canadian workers from being undercut by cheaper foreign labour — but it also means the process is slow and bureaucratic.', '[{"title":"Temporary Foreign Worker Program","slug":"temporary-foreign-worker-program"},{"title":"Work Permit","slug":"work-permit"},{"title":"IRCC","slug":"ircc"}]', 'What does a positive Labour Market Impact Assessment (LMIA) demonstrate?', '["That the foreign worker has the required qualifications","That hiring a foreign worker will not negatively affect Canadian workers and that the employer could not find a qualified Canadian","That the employer has enough revenue to pay the worker''s salary","That the provincial government approves of the hiring decision"]', 1, 'LMIA — Canadian Citizenship Glossary | PassPilot', 'What is an LMIA? Learn about Labour Market Impact Assessments and their role in Canadian work permit applications.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('International Student Program', 'international-student-program', 'Canada''s program for foreign students, who require a study permit to attend a designated learning institution (DLI) for programs longer than six months.', 'Canada is one of the world''s top destinations for international students. Foreign nationals who want to study in Canada for more than six months generally need a study permit, issued by IRCC. The student must be accepted by a Designated Learning Institution (DLI) — a school approved by a provincial or territorial government to host international students.

International students in Canada have the right to work on campus without a separate work permit and can work off campus for up to 24 hours per week (recently increased to allow more hours during certain periods). After graduation, students may apply for a Post-Graduate Work Permit (PGWP) that allows them to work in Canada for up to three years, depending on the length of their program. Canadian education and work experience gained through the student pathway is a valuable route to permanent residency through Express Entry''s Canadian Experience Class.', 'Canada actively recruits international students — they bring tuition money, fill university spots, and often become skilled workers who stay permanently. After graduating, students can get a work permit for up to 3 years. Many then use that Canadian work experience to apply for PR through the Canadian Experience Class. For many people, the ''student to PR'' pathway is the most accessible route to Canadian citizenship.', '[{"title":"Study Permit","slug":"study-permit"},{"title":"Canadian Experience Class","slug":"canadian-experience-class-detail"},{"title":"IRCC","slug":"ircc"}]', 'What opportunity is available to international students in Canada after they graduate from a qualifying program?', '["Automatic permanent residence after graduation","A Post-Graduate Work Permit (PGWP) allowing them to work in Canada for up to 3 years","Immediate citizenship if their GPA is above 3.5","A 2-year tourist visa extension"]', 1, 'International Student Program — Canadian Citizenship Glossary | PassPilot', 'What is Canada''s International Student Program? Learn about study permits, work rights, and the pathway to permanent residence.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Caregiver Program', 'caregiver-program', 'Federal immigration programs for foreign nationals who care for children, elderly persons, or people with medical needs, with pathways to permanent residence.', 'Canada''s caregiver programs allow foreign nationals to come to Canada to provide care for children or adults who need assistance due to age, disability, or illness. Historically, this was the Live-in Caregiver Program (LCP), which required caregivers to live in their employer''s home. The LCP has been replaced with two main pathways: the Home Child Care Provider Pilot and the Home Support Worker Pilot, which allow applicants to apply for permanent residence from within Canada after gaining Canadian work experience.

Caregivers under these newer programs can have open work permits — allowing them to change employers — and do not need to live in the employer''s home. After completing the required hours of Canadian caregiving work, applicants can apply for permanent residence under the caregiver category. This is an important pathway for migrants from countries like the Philippines who have a long tradition of working in caregiving professions in Canada.', 'Canada has an aging population that needs care workers, and the Caregiver Program brings in people specifically for this work. The program has improved over the years — caregivers no longer have to live in their employer''s home, and they can work toward permanent residence. For many Filipinos and other caregivers, this is their path to becoming Canadian.', '[{"title":"Work Permit","slug":"work-permit"},{"title":"Open Work Permit","slug":"open-work-permit"},{"title":"IRCC","slug":"ircc"}]', 'What is a key improvement in Canada''s newer caregiver pathways compared to the old Live-in Caregiver Program?', '["Caregivers are now paid by the federal government directly","Caregivers can have open work permits and no longer need to live in the employer''s home","Caregivers receive automatic permanent residence immediately upon arrival","Caregivers are now exempt from all language requirements"]', 1, 'Caregiver Program — Canadian Citizenship Glossary | PassPilot', 'What is Canada''s Caregiver Program? Learn about work permits, pathways to PR, and Canada''s caregiver immigration streams.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Citizenship by Descent', 'citizenship-by-descent', 'Acquisition of Canadian citizenship at birth through a Canadian parent, even when born outside Canada — with limitations introduced in 2009 (first-generation limit).', 'Before 2009, Canadians could pass citizenship to their children and grandchildren born abroad, potentially for generations. In 2009, the Citizenship Act was amended to introduce the ''first-generation limit'': children born abroad to a Canadian parent are Canadian citizens automatically only if at least one parent was born in Canada or became a Canadian citizen through naturalization (grant). Children born abroad to a parent who was themselves born abroad (second generation) are no longer automatically Canadian citizens.

People who lost or never received citizenship due to the second-generation cutoff could apply for a grant of citizenship under certain circumstances. Citizenship by descent must be formally registered — children born abroad to Canadian parents need a Citizenship Certificate to prove their citizenship. This can be applied for from birth. Canadian citizenship acquired by descent carries the same rights and responsibilities as citizenship acquired by birth in Canada or through naturalization.', 'If your parent is Canadian and they were born in Canada (or became Canadian through naturalization), you''re automatically Canadian even if you''re born in another country. But if your parent was born abroad to a Canadian grandparent, you are NOT automatically Canadian under the rules introduced in 2009. The government closed the ''citizenship by descent'' chain at one generation to prevent people from passing citizenship indefinitely without any real connection to Canada.', '[{"title":"Canadian Citizen","slug":"canadian-citizen"},{"title":"Citizenship Certificate","slug":"citizenship-certificate"},{"title":"Dual Citizenship","slug":"dual-citizenship"}]', 'Under the first-generation limit introduced in 2009, a child born abroad is automatically a Canadian citizen only if:', '["Their parents lived in Canada for at least 5 years","At least one parent was born in Canada or acquired citizenship through naturalization","Both parents are Canadian citizens by descent","The child applies before the age of 18"]', 1, 'Citizenship by Descent — Canadian Citizenship Glossary | PassPilot', 'What is Canadian citizenship by descent? Learn about the first-generation limit and how citizenship passes to children born abroad.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Renunciation of Citizenship', 'renunciation-of-citizenship', 'The voluntary process by which a Canadian citizen formally gives up their Canadian citizenship, which is irreversible unless they reapply.', 'A Canadian citizen may voluntarily renounce their citizenship by applying to IRCC. The applicant must be 18 or older, be a citizen of another country (to avoid being stateless), and not be in Canada (or be in Canada with the intention of living in another country). Once approved, renunciation is effective from the date IRCC grants it — it cannot be undone without applying for citizenship again through the regular or simplified grant process.

A person who has renounced citizenship may resume citizenship under certain circumstances — for example, if the renunciation was made under duress or as a minor. However, voluntary adult renunciation is considered final unless a new application is approved. Common reasons for renunciation include foreign employment restrictions in government or military positions that prohibit dual citizenship, foreign nationality laws, or personal choice. Renouncing Canadian citizenship does not affect Canadian-born children''s citizenship.', 'It''s possible to give up Canadian citizenship — but it''s serious and mostly permanent. You can only do it if you have another citizenship (Canada won''t make you stateless). Common reasons include certain foreign government jobs that ban dual citizenship. Once you renounce, you''re no longer Canadian and would need to apply through the regular process to get it back. Think carefully before renouncing one of the world''s most valuable passports!', '[{"title":"Canadian Citizen","slug":"canadian-citizen"},{"title":"Dual Citizenship","slug":"dual-citizenship"},{"title":"Citizenship Certificate","slug":"citizenship-certificate"}]', 'What is a key requirement for renouncing Canadian citizenship?', '["You must have lived outside Canada for at least 10 years","You must be a citizen of another country to avoid becoming stateless","You must be over 25 years of age","You must first complete 3 years of service to a foreign government"]', 1, 'Renunciation of Citizenship — Canadian Citizenship Glossary | PassPilot', 'What is renunciation of Canadian citizenship? Learn who can renounce, why, and whether it can be reversed.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Regulated Professions', 'regulated-professions', 'Occupations in Canada (such as medicine, law, engineering, and nursing) whose practice is governed by licensing bodies that require credentials assessment and may require additional training for foreign-trained professionals.', 'In Canada, many professions are regulated at the provincial or territorial level by self-governing regulatory bodies. Regulated professions include doctors, nurses, engineers, lawyers, teachers, social workers, pharmacists, architects, and many others. To work in a regulated profession, a professional must be licensed by the relevant body in the province where they wish to practise, regardless of their qualifications from abroad.

Foreign-trained professionals often face challenges when immigrating to Canada because their credentials must be assessed for equivalency. This process can involve credential recognition through national or provincial bodies, additional examinations, supervised practice periods, or bridge training programs. IRCC and provincial governments have invested in programs to facilitate ''fair registration practices'' and reduce unnecessary barriers for internationally trained professionals. The National Occupational Classification (NOC) system helps categorize both regulated and non-regulated occupations for immigration purposes.', 'Imagine being a doctor in India, immigrating to Canada, and then being told you need to requalify because your medical degree isn''t automatically recognized. That''s the regulated professions challenge. Canada recognizes that its licensing system can be unfair to skilled immigrants, which is why the government has been investing in programs to help internationally trained professionals get back into their field faster.', '[{"title":"IRCC","slug":"ircc"},{"title":"Express Entry","slug":"express-entry"},{"title":"Canadian Experience Class","slug":"canadian-experience-class-detail"}]', 'Why might an internationally trained professional face challenges when working in their field in Canada?', '["Canada does not recognize any foreign university degrees","Professional licensing in Canada is regulated by provincial bodies that may require credential assessment, additional exams, or bridge training","The federal government sets a quota on how many foreign professionals can work in each field","All foreign professionals must work for at least 2 years in an unrelated field before qualifying"]', 1, 'Regulated Professions — Canadian Citizenship Glossary | PassPilot', 'What are regulated professions in Canada? Learn about licensing, credential recognition, and challenges for internationally trained professionals.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('Truth and Reconciliation Commission Calls to Action', 'trc-calls-to-action', '94 specific recommendations issued by the Truth and Reconciliation Commission in 2015 to address the legacy of residential schools and advance reconciliation with Indigenous peoples.', 'The Truth and Reconciliation Commission of Canada (TRC), which concluded its work in 2015, issued 94 Calls to Action — specific recommendations directed at governments, institutions, churches, corporations, and individual Canadians. The Calls to Action address areas including child welfare, education, language and culture, health, justice, and commemoration. They call on governments at all levels to take concrete steps to repair the damage done by the residential school system and the ongoing effects of colonialism.

Some notable Calls to Action include: implementing the United Nations Declaration on the Rights of Indigenous Peoples (UNDRIP); revising the oath of citizenship to include acknowledgment of treaty rights; requiring Indigenous history in K-12 education; establishing a National Day for Truth and Reconciliation (September 30 — completed in 2021); and addressing the over-representation of Indigenous peoples in the justice system. As of 2023, Canada has fully implemented approximately 13 of the 94 Calls to Action, with many others in progress.', 'The TRC''s 94 Calls to Action are like a to-do list for fixing what the residential school system broke. They cover everything from how kids are taught history in school, to how judges treat Indigenous defendants, to what new citizens promise in their oath. Progress has been slow — only about 13 of the 94 have been fully completed. Reconciliation is real work, not just words.', '[{"title":"Truth and Reconciliation Commission","slug":"truth-and-reconciliation-commission"},{"title":"Residential Schools","slug":"residential-schools"},{"title":"Indigenous Peoples","slug":"indigenous-peoples"}]', 'How many Calls to Action did the Truth and Reconciliation Commission issue in 2015?', '["25","52","94","137"]', 2, 'TRC Calls to Action — Canadian Citizenship Glossary | PassPilot', 'What are the TRC''s 94 Calls to Action? Learn about the Truth and Reconciliation Commission''s recommendations for Canada.', 'pro', 'active');
INSERT OR IGNORE INTO dictionary_terms (title, slug, short_definition, full_description, ai_explanation, related_terms, quiz_question, quiz_options, quiz_answer, seo_title, seo_description, access_level, status) VALUES ('UNDRIP', 'undrip', 'United Nations Declaration on the Rights of Indigenous Peoples — adopted by Canada in 2016 and enacted into Canadian law in 2021, affirming Indigenous peoples'' rights.', 'The United Nations Declaration on the Rights of Indigenous Peoples (UNDRIP) was adopted by the UN General Assembly in 2007. Canada initially abstained, then endorsed UNDRIP in 2016 under Prime Minister Justin Trudeau. In 2021, Canada passed the United Nations Declaration on the Rights of Indigenous Peoples Act, making Canada the first country to enact UNDRIP into domestic law. The Act requires the federal government to take all measures necessary to ensure its laws are consistent with UNDRIP.

Key rights affirmed by UNDRIP include: the right to self-determination, the right to maintain and strengthen distinct institutions, the right to free, prior, and informed consent (FPIC) before governments and companies undertake projects on Indigenous lands, and the right to maintain and develop cultural identity, language, and traditions. UNDRIP is central to Canada''s reconciliation commitments and is referenced in the TRC''s Calls to Action.', 'UNDRIP is an international agreement that says Indigenous peoples around the world have the right to govern themselves, protect their culture, and say yes or no to things happening on their land. Canada was actually slow to support it (it abstained in 2007!), but in 2021 became the first country to make it domestic law. Now the government must make sure Canadian laws respect Indigenous rights as defined in UNDRIP.', '[{"title":"Indigenous Peoples","slug":"indigenous-peoples"},{"title":"TRC Calls to Action","slug":"trc-calls-to-action"},{"title":"Self-Government","slug":"self-government"}]', 'In what year did Canada pass legislation making UNDRIP (United Nations Declaration on the Rights of Indigenous Peoples) domestic Canadian law?', '["2007","2010","2016","2021"]', 3, 'UNDRIP — Canadian Citizenship Glossary | PassPilot', 'What is UNDRIP? Learn about the UN Declaration on the Rights of Indigenous Peoples and Canada''s 2021 legislation.', 'pro', 'active');